    "content": "<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Ben 10 clássico · Clareira LIVE · V42.4</title><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Ccircle cx='20' cy='20' r='19' fill='%23b7f35a'/%3E%3Cpath d='M10 9H30L23 20L30 31H10L17 20Z' fill='%2311241b'/%3E%3C/svg%3E\"><link rel=\"stylesheet\" href=\"/arena.css\"><link rel=\"stylesheet\" href=\"/classic-ui.css\"><link rel=\"stylesheet\" href=\"/live-effects.css\"><link rel=\"stylesheet\" href=\"/dna-energy.css\"><link rel=\"stylesheet\" href=\"/broadcast-ui.css\"></head>\n<body><canvas id=\"city\" aria-label=\"Clareira tridimensional do acampamento\"></canvas><div id=\"flash\"></div><div id=\"world-labels\"></div>\n<header><a class=\"logo\" href=\"#\" aria-label=\"Ben 10\"><span class=\"classic-brand-mark\">◈</span><b>BEN<span>10</span></b><small>ACAMPAMENTO · LIVE <span id=\"build-version\">V42.4</span></small></a><div id=\"connection\">● DEMO LOCAL</div><span id=\"day-phase\">☀ DIA</span><button id=\"fullscreen\" aria-label=\"Tela cheia\">⛶</button></header>\n<main id=\"arena-ui\">\n<div class=\"omni-topline\"><span><i></i> OMNITRIX <b>LIVE</b></span><span>CLAREIRA DO BEN</span><button id=\"show-controls\" aria-expanded=\"false\">Controles ▸</button></div>\n<section class=\"omni-energy\" aria-label=\"Energia coletiva da LIVE\"><div id=\"omni-level\">1</div><div class=\"omni-energy-content\"><div><strong><span id=\"omni-form\">BEN 10</span> <span id=\"omni-rank\">PORTADOR</span></strong><b id=\"omni-energy-text\">0 / 250 EP</b></div><progress id=\"omni-meter\" value=\"0\" max=\"100\" aria-label=\"Energia coletiva\"></progress><small id=\"omni-next\">PRÓXIMO: HERÓI · CURTIDAS + CHAT + PRESENTES</small><div id=\"dna-collection\"><small id=\"dna-source\">ENERGIA · DEMO</small><div class=\"dna-line\"><span id=\"dna-icon\">♨</span><strong id=\"dna-next\">LIBERAR CHAMA</strong><b id=\"dna-remaining\">FALTAM 100 CURTIDAS</b></div><progress id=\"dna-meter\" max=\"100\" value=\"0\" aria-label=\"Energia para desbloquear o próximo alien\"></progress></div></div><span class=\"omni-emblem\">◈</span></section>\n<section id=\"watch-hud\" data-phase=\"ready\" aria-label=\"Estado do Omnitrix\"><button id=\"watch-select\" title=\"Selecionar alien\" aria-label=\"Selecionar alien no Omnitrix\"><svg viewBox=\"0 0 100 100\" aria-hidden=\"true\"><defs><radialGradient id=\"watch-face-light\"><stop stop-color=\"#d4ff89\"/><stop offset=\"1\" stop-color=\"#82c838\"/></radialGradient></defs><circle class=\"watch-housing\" cx=\"50\" cy=\"50\" r=\"47\"/><path class=\"watch-lugs\" d=\"M34 4H66V17H34ZM34 83H66V96H34ZM4 34H17V66H4ZM83 34H96V66H83Z\"/><circle class=\"watch-bezel\" cx=\"50\" cy=\"50\" r=\"35\"/><circle class=\"watch-dial\" cx=\"50\" cy=\"50\" r=\"28\"/><path class=\"watch-hourglass\" d=\"M33 29H67L55 50L67 71H33L45 50Z\"/><g class=\"watch-screws\"><circle cx=\"22\" cy=\"22\" r=\"3\"/><circle cx=\"78\" cy=\"22\" r=\"3\"/><circle cx=\"22\" cy=\"78\" r=\"3\"/><circle cx=\"78\" cy=\"78\" r=\"3\"/></g></svg></button><div class=\"watch-info\"><div><strong id=\"watch-form\">BEN TENNYSON</strong><time id=\"watch-timer\">PRONTO</time></div><progress id=\"watch-charge\" value=\"100\" max=\"100\" aria-label=\"Carga do Omnitrix\"></progress><p id=\"watch-status\">Relógio carregado · selecione uma forma</p></div></section>\n<section class=\"omni-gifts\" aria-label=\"Presentes em slides\"></section>\n<div class=\"scene-label\"><i></i> CLAREIRA DO ACAMPAMENTO <span>O CHAT DECIDE A AVENTURA</span></div>\n<div id=\"engagement-hook\"><strong>VOCÊ CONTROLA O BEN</strong><span>COMENTE <b>PULAR</b></span></div><aside class=\"omni-command-card\" aria-label=\"Comandos do chat\"><button id=\"help-toggle\" aria-expanded=\"false\">💬 COMANDE NO CHAT</button><div><span>↟ PULAR</span><span>↠ CORRER</span><span>↑ VOAR</span><span>⚡ TREINAR</span><span>♨ CHAMA</span><span>✹ PODER</span></div><p>Presentes ganham efeitos no cenário</p></aside>\n<section id=\"chat-goals\" aria-label=\"Missões coletivas do chat\"><div class=\"goal-kicker\"><small id=\"goal-source\">MISSÃO · DEMO</small><div id=\"goal-tabs\" aria-label=\"Escolher missão\"></div></div><div class=\"goal-heading\"><span id=\"goal-icon\">♥</span><strong id=\"goal-title\">TAP TAP OMNITRIX</strong></div><progress id=\"goal-progress\" value=\"0\" max=\"500\" aria-label=\"Progresso da missão\"></progress><span id=\"goal-count\">0 / 500 curtidas</span><p id=\"goal-reward\">LIBERA: Explosão Omnitrix</p></section><aside id=\"live-ranking\" aria-label=\"Ranking da LIVE\"><div class=\"live-rank-head\"><strong>🏆 TOP DA LIVE</strong><button id=\"rank-collapse\" title=\"Recolher ranking\" aria-expanded=\"true\">−</button><button id=\"rank-hide\" title=\"Ocultar ranking\" aria-label=\"Ocultar ranking\">×</button></div><ol id=\"live-rank-list\"></ol><div id=\"energy\" hidden></div></aside>\n<section id=\"command-help\" hidden><strong>ESCREVA NO CHAT</strong><p>Chama · XLR8 · Diamante · Quatro Braços</p><p>Andar esquerda · correr direita · frente · trás</p><p>Pular · girar · parar · voar · pousar</p><p>Poder 1 · poder 2 · poder 3 · humano</p><p>Sentar · levantar · sorrir · acenar · comemorar · pose · vitória</p><small>Voar exige Chama, Fantasmático ou Alien X. Supervelocidade exige XLR8. Relógio vermelho precisa recarregar.</small></section>\n<div id=\"heart-layer\" aria-hidden=\"true\"></div><div id=\"live-toasts\" aria-live=\"polite\"></div><div id=\"ai-mode\" data-mode=\"local\" role=\"status\">● RESPOSTA LOCAL</div><div id=\"subtitles\" aria-live=\"polite\"></div><div id=\"scene-announcement\" hidden><small id=\"announcement-label\"></small><strong id=\"announcement-title\"></strong></div>\n<div class=\"arena-bottom\"><div class=\"activity\"><span id=\"activity\">Aguardando a escolha do chat</span><small id=\"speech-queue\" hidden></small><small id=\"telemetry\">WEBGL</small></div><div id=\"gift-action-status\" hidden></div><div id=\"classic-forms\" class=\"forms\" hidden aria-label=\"Formas do Omnitrix\"></div><div class=\"main-controls\"><button id=\"open-aliens\">◈ Omnitrix</button><button id=\"open-actions\">✦ Ações</button><button id=\"panel-toggle\">☷ LIVE</button><button id=\"sound\" aria-label=\"Ativar voz IA e sons\" title=\"Ativar voz IA e sons\">♫</button></div><form id=\"chat\" hidden><input id=\"message\" maxlength=\"500\" placeholder=\"Pergunte ao Ben ou comande: PULAR…\" required autocomplete=\"off\"><button>Enviar ↗</button></form></div>\n<section id=\"quick-actions\" class=\"floating-panel\" hidden><div class=\"drawer-head\"><strong>AÇÕES DA LIVE</strong><button id=\"close-actions\" aria-label=\"Fechar ações\">×</button></div><div class=\"quick-grid\"><button id=\"tap-tap\" aria-label=\"TAP TAP · testar corações\"><strong>◉ TAP TAP</strong><small id=\"tap-mode\">TESTE LOCAL</small></button><button id=\"open-powers\">✹ Poderes</button><button id=\"open-controls\">↠ Movimentar</button><button id=\"toggle-test-chat\">💬 Testar chat</button><button id=\"camera-home\">⛶ Voltar ao Ben</button></div></section><section id=\"alien-picker\" class=\"floating-panel\" hidden><div class=\"drawer-head\"><div><small>DNA DO OMNITRIX</small><h2>Escolha uma forma</h2></div><button id=\"close-aliens\" aria-label=\"Fechar seleção\">×</button></div><div id=\"forms\"></div><p id=\"selected-description\">Selecione o alien e confirme a transformação.</p><button id=\"confirm-transform\">TRANSFORMAR ◈</button><button id=\"revert-human\">Voltar a Ben</button></section>\n<section id=\"power-picker\" class=\"floating-panel\" hidden><div class=\"drawer-head\"><h2>Poderes da forma</h2><button id=\"close-powers\" aria-label=\"Fechar poderes\">×</button></div><div id=\"power-choices\"></div><p id=\"power-status\">O chat também pode pedir poder 1, 2 ou 3.</p></section>\n<section id=\"movement-pad\" class=\"floating-panel\" hidden><div class=\"drawer-head\"><strong>ANDAR LIVRE</strong><button id=\"close-controls\" aria-label=\"Fechar movimento\">×</button></div><select id=\"movement-mode\" aria-label=\"Modo de movimento\"><option value=\"walk\">Andar</option><option value=\"run\">Correr</option><option value=\"dash\">XLR8 · supervelocidade</option><option value=\"fly\">Voar · formas compatíveis</option></select><div class=\"dpad\"><button data-dir=\"0,1\">↑ Frente</button><button data-dir=\"-1,0\">← Esquerda</button><button id=\"stop-movement\">■ Parar</button><button data-dir=\"1,0\">Direita →</button><button data-dir=\"0,-1\">↓ Trás</button></div><div class=\"movement-extra\"><button id=\"jump\">↟ Pular</button><button id=\"spin\">⟳ Girar</button><button id=\"land\">↓ Pousar</button><button data-gesture=\"sit\">▱ Sentar</button><button data-gesture=\"stand\">↟ Levantar</button><button data-gesture=\"wave\">✋ Acenar</button><button data-gesture=\"smile\">☺ Sorrir</button><button data-gesture=\"hero\">◈ Pose de herói</button><button data-gesture=\"fistpump\">✊ Vitória</button></div></section>\n</main>\n<dialog id=\"panel\"><div class=\"drawer-head\"><div><small>CENTRAL DA TRANSMISSÃO</small><h2>Clareira LIVE</h2></div><button id=\"close\" aria-label=\"Fechar painel\">×</button></div><nav id=\"tabs\"><button data-tab=\"live\">LIVE</button><button data-tab=\"audio\">IA e voz</button><button data-tab=\"gifts\">Laboratório</button><button data-tab=\"ranking\">Ranking</button><button data-tab=\"settings\">Ajustes</button></nav>\n<section id=\"tab-live\"><h3>Conectar pelo @</h3><label>Usuário TikTok<input id=\"username\" placeholder=\"@seuusuario\" autocapitalize=\"off\" spellcheck=\"false\"></label><label>Conector<select id=\"provider\"><option value=\"auto\">Automático</option><option value=\"piratetok\">PirateTok</option><option value=\"alternative\">TikTok Live Connector</option></select></label><label>Rota<select id=\"live-endpoint\"><option value=\"auto\">Automática</option><option value=\"global\">Global</option><option value=\"us\">Américas</option><option value=\"eu\">Europa</option></select></label><button id=\"connect\">Conectar LIVE</button><button id=\"disconnect\">Desconectar</button><p id=\"live-summary\" role=\"status\">Nenhuma conexão real confirmada.</p><details><summary>Diagnóstico</summary><pre id=\"live-diagnostic\"></pre></details><label><input id=\"live-shoutouts\" type=\"checkbox\" checked> Ben recebe visitantes e agradece ao público</label><label><input id=\"keep-awake\" type=\"checkbox\"> Manter tela ligada</label><p>Use a captura de tela do TikTok e mantenha o Chrome com o jogo em primeiro plano. A transmissão depende do acesso da sua conta e do conector comunitário.</p></section>\n<section id=\"tab-audio\" hidden>\n<h3>Conversa do Ben clássico</h3>\n<label>Onde o Ben pensa<select id=\"conversation-provider\"><option value=\"gemini\">Gemini · online</option><option value=\"local\">IA no aparelho · sem chave</option></select></label>\n<p id=\"ai-health\" role=\"status\">Teste a conversa para confirmar que a IA respondeu.</p>\n<div id=\"local-ai-setup\" hidden><h3>IA e voz no seu celular</h3><p>Baixe os modelos uma vez no Termux. Depois, conversa e voz funcionam sem chave. O TikTok continua precisando de internet.</p><code>bash local-ai.sh install</code><p>Para ligar a IA e o jogo:</p><code>bash local-ai.sh start</code><p>Modelo de conversa de 4B e voz neural em português. O perfil inicial foi preparado para o Realme GT3 com 16 GB. A velocidade e o timbre precisam ser conferidos no aparelho.</p><p>Se a voz trocar o R pelo L, compare outro modelo brasileiro. Pare a IA com Ctrl+C, execute <code>bash local-ai.sh voice cadu</code> e reinicie. Isso baixa somente a voz; o modelo de conversa continua instalado. Faber e Jeff também podem ser selecionados pelo mesmo comando.</p><button id=\"use-local-ai\">Usar conversa e voz locais</button><button id=\"check-local-ai\">Verificar serviços locais</button><pre id=\"local-ai-status\">Aguardando verificação.</pre></div>\n<div id=\"gemini-settings\"><p>Cadastre até 20 chaves e escolha qual usar no Gemini.</p>\n<form id=\"key-form\"><label>Nome da chave<input id=\"key-label\" placeholder=\"Meu projeto\"></label><label>Chave API<input id=\"key-value\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" required></label><button>Adicionar e usar esta chave</button></form>\n<details><summary>Adicionar várias chaves de uma vez</summary><form id=\"bulk-key-form\"><label>Uma chave por linha<textarea id=\"bulk-keys\" rows=\"4\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" required></textarea></label><button>Adicionar todas</button></form></details><div id=\"key-list\"></div><p id=\"key-status\" role=\"status\"></p>\n<label>Modelo Gemini<input id=\"gemini-model\" value=\"auto\" list=\"gemini-model-options\" spellcheck=\"false\"></label><datalist id=\"gemini-model-options\"><option value=\"auto\">Automático · modelo Flash disponível</option></datalist><button id=\"load-gemini-models\">Consultar modelos da minha chave</button><p>Chaves e seleção ficam no servidor local. As cotas dependem do projeto no Google AI Studio.</p></div>\n<label>Pergunta de teste<input id=\"ai-test-prompt\" value=\"Qual é o seu alien favorito?\" maxlength=\"300\"></label><button id=\"test-gemini\">Testar conversa selecionada</button><p id=\"ai-sample\" role=\"status\"></p><p id=\"conversation-status\" role=\"status\">Aguardando teste ou comentário.</p>\n<h3>Voz do Ben clássico</h3><label>Onde a voz é gerada<select id=\"voice-provider\"><option value=\"local\">Piper · neural no aparelho</option><option value=\"gemini\">Gemini · voz IA online</option><option value=\"elevenlabs\">ElevenLabs · voz IA online</option></select></label>\n<div id=\"gemini-voice-settings\"><label>Modelo Gemini TTS<input id=\"tts-model\" value=\"auto\" spellcheck=\"false\"></label><label>Voz Gemini do Ben<select id=\"gemini-voice\"><option>Puck</option><option>Zephyr</option><option>Charon</option><option>Kore</option><option>Fenrir</option><option>Aoede</option><option>Leda</option><option>Orus</option></select></label></div>\n<p>Ben mantém a personalidade do clássico e a mesma voz em todas as formas. O áudio recebe somente a frase. Nenhum provedor usa a voz do aparelho como substituta.</p><button id=\"save-voice-provider\">Salvar voz IA</button><label>Frase para testar a pronúncia<input id=\"tts-test-text\" maxlength=\"300\" value=\"Agora o relógio está pronto. Quatro Braços corre rápido. Bora transformar!\"></label><button id=\"test-tts\">Ouvir voz e pronúncia</button><pre id=\"voice-diagnostic\">Toque em ♫ para ativar as vozes.</pre>\n<details id=\"eleven-voice-settings\"><summary>Configurar ElevenLabs</summary><label>ID de voz ElevenLabs<input id=\"eleven-voice-id\" autocomplete=\"off\"></label><form id=\"eleven-key-form\"><label>Chave ElevenLabs<input id=\"eleven-key\" type=\"password\" autocomplete=\"off\" required></label><button>Salvar chave ElevenLabs</button></form><p id=\"eleven-status\"></p></details>\n<label>Voz<input type=\"range\" id=\"voice-volume\" min=\"0\" max=\"1\" step=\".05\" value=\"1\"></label><label>Ambiente<input type=\"range\" id=\"music-volume\" min=\"0\" max=\"1\" step=\".05\" value=\".15\"></label><label>Efeitos<input type=\"range\" id=\"sfx-volume\" min=\"0\" max=\"1\" step=\".05\" value=\".3\"></label>\n<p>Piper usa um modelo neural local em português; não é a gravação da dublagem. Os serviços online dependem de chave e cota. Em caso de falha, as legendas continuam e o painel informa o motivo.</p></section>\n<section id=\"tab-gifts\" hidden><h3>DNA por TAP TAP</h3><p>Esferas verdes representam curtidas. A energia acumulada libera as transformações e fica salva no aparelho. DEMO e LIVE têm progressos separados.</p><form id=\"unlock-settings\"><label><input id=\"unlocks-enabled\" type=\"checkbox\" checked> Desbloquear aliens por curtidas</label><details><summary>Metas de curtidas de cada alien</summary><div id=\"unlock-targets\" class=\"goal-setting-grid\"></div></details><button>Salvar desbloqueios</button><button type=\"button\" id=\"reset-unlocks\">Recomeçar DNA desta origem</button></form><p id=\"unlock-summary\" role=\"status\"></p><h3>Missões do chat</h3><p>Curtidas, comentários, compartilhamentos e novos seguidores preenchem metas e liberam celebrações 3D. O progresso da LIVE fica separado do DEMO.</p><form id=\"goal-settings\"><label><input id=\"goals-enabled\" type=\"checkbox\" checked> Ativar missões coletivas</label><div class=\"goal-setting-grid\"><label>♥ Curtidas<input id=\"goal-setting-like\" type=\"number\" min=\"1\" max=\"1000000\" value=\"500\" required></label><label>💬 Comentários<input id=\"goal-setting-comment\" type=\"number\" min=\"1\" max=\"10000\" value=\"20\" required></label><label>↗ Compartilhamentos<input id=\"goal-setting-share\" type=\"number\" min=\"1\" max=\"10000\" value=\"3\" required></label><label>★ Seguidores<input id=\"goal-setting-follow\" type=\"number\" min=\"1\" max=\"10000\" value=\"3\" required></label></div><button>Salvar metas</button><button type=\"button\" id=\"reset-goals\">Recomeçar metas desta sessão</button></form><p id=\"goals-summary\" role=\"status\"></p><h3>Regras dos presentes</h3><p>Cada presente pode escolher um alien, acionar poder e movimento. As missões coletivas da LIVE liberam efeitos 3D. Durante a recarga os pedidos de transformação aguardam na fila.</p><textarea id=\"rules\" rows=\"12\" aria-label=\"Regras de presentes JSON\"></textarea><button id=\"save-rules\">Salvar regras</button><h3>Teste local</h3><label>Nome do visitante<input id=\"demo-user\" value=\"Visitante de teste\"></label><label>Evento<select id=\"demo-type\"><option>gift</option><option>join</option><option>follow</option><option>like</option><option>share</option></select></label><label>Presente<select id=\"gift\"></select></label><button id=\"demo\">Disparar DEMO local</button><p>O DEMO não compra nem envia presentes ao TikTok.</p></section>\n<section id=\"tab-ranking\" hidden><h3>Quem faz a LIVE acontecer</h3><ol id=\"ranking\"></ol></section><section id=\"tab-settings\" hidden><label><input id=\"show-ranking\" type=\"checkbox\" checked> Mostrar ranking da LIVE</label><h3>Dia, tarde e noite</h3><label>Ambiente<select id=\"clock-mode\"><option value=\"cycle\">Ciclo automático</option><option value=\"day\">Dia</option><option value=\"sunset\">Tarde</option><option value=\"night\">Noite</option></select></label><label>Duração do ciclo (minutos)<input id=\"clock-minutes\" type=\"number\" min=\"3\" max=\"30\" value=\"12\"></label><button id=\"save-clock\">Salvar ambiente</button><h3>Ciclo do Omnitrix</h3><label>Duração da forma (20–120 s)<input id=\"watch-duration\" type=\"number\" min=\"20\" max=\"120\" value=\"45\"></label><label>Recarga (8–60 s)<input id=\"watch-recharge\" type=\"number\" min=\"8\" max=\"60\" value=\"18\"></label><label><input id=\"auto-wander\" type=\"checkbox\"> Passeio contínuo pela clareira (opcional)</label><label><input id=\"idle-life\" type=\"checkbox\" checked> Gestos e pequenos passeios ocasionais</label><button id=\"save-watch\">Salvar relógio</button><h3>Imagem e desempenho</h3><label>Qualidade<select id=\"quality\"><option value=\"economy\">Econômico</option><option value=\"balanced\" selected>Equilibrado</option><option value=\"high\">Alto</option></select></label><label>Distância da câmera<input type=\"range\" id=\"camera-distance\" min=\"1\" max=\"1.6\" step=\".05\" value=\"1.1\"></label><h3>Modelos e licenças</h3><div id=\"model-credits\"></div><pre id=\"model-result\" hidden></pre><p>Quatro Braços, Alien X e Cipó Selvagem usam as novas malhas procedurais por padrão. Arquivos personalizados salvos no aparelho continuam disponíveis.</p></section><p id=\"panel-error\" role=\"alert\"></p></dialog>\n<section id=\"welcome\"><small>V42.4 · IA E VOZ NO APARELHO</small><h1>O chat escolhe.<br>Ben vira herói.</h1><p>Uma clareira para andar livre, testar poderes e transformar com o Omnitrix. Verde: carregado. Vermelho: recarregando.</p><button id=\"enter-game\">ENTRAR NA CLAREIRA</button><button id=\"enter-live\">Conectar meu TikTok</button><small>Ative ♫ para voz IA e efeitos.</small></section>\n<script src=\"/vendor/babylon.js\"></script><script src=\"/vendor/babylonjs.loaders.min.js\"></script><script type=\"module\" src=\"/arena-app.js\"></script></body></html>\n"
  },
  {
    "name": "public/arena-app.js",
    "sha256": "ee0efc3e5f7cc9c8a3b3050bcae2cdd02a666eab8b4927f9efcc74f6048aa3df",
    "content": "import {AlienUnlockUI} from './alien-unlock-ui.js';\nimport {HeartStream} from './heart-stream.js';\nimport {ChatGoalUI} from './chat-goal-ui.js';\nimport {replyReaction} from './ben-behavior.js';\nimport {ClassicLiveUI,FORM_ICONS} from './classic-live-ui.js';\nimport {BUILD_ID} from './release.js';\nimport {World,forms,names} from './world.js';\nimport {SPEAKERS} from './characters.js';\nimport {powerAbility} from './transformations.js';\nimport {CinematicAudio} from './cinematic-audio.js';\nimport {GiftSlideshow} from './gift-slides.js';\nimport {LiveDialogueQueue} from './ben-dialogue.js';\nimport {liveEventPresentation} from './live-engagement.js';\nconst $=id=>document.getElementById(id);\nconst error=e=>{const text=e.message||String(e);$('panel-error').textContent=text;notice(text);};\nasync function api(route,data){const r=await fetch('/api/'+route,data===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)}),body=await r.json();if(!r.ok)throw Object.assign(Error(body.error||'Falha '+r.status),{code:body.code,status:r.status});return body;}\nlet world;try{world=new World($('city'),s=>{$('telemetry').textContent=s.fps+' FPS';});window.linelWorld=world;world.cameraZoom=Number(localStorage.getItem('ben36Camera')||1.1);world.reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){$('subtitles').textContent='WebGL não iniciou: '+e.message;}\nclass AudioManager {\n constructor(){this.enabled=false;this.ctx=null;this.voice=1;this.music=.15;this.sfx=.3;this.speaking=false;this.voiceRetryAt=0;this.voiceBlocked=false;this.audio=null;this.finish=null;this.notes=[261.63,329.63,392,523.25,440,392,329.63,293.66];this.note=0;}\n async unlock(){this.ctx??=new AudioContext();await this.ctx.resume();this.enabled=true;this.voiceRetryAt=0;this.voiceBlocked=false;$('sound').textContent='♫';$('sound').classList.add('sound-on');$('sound').title='Som e voz IA ativados';$('voice-diagnostic').textContent='Som ativo. Todas as falas usam o provedor de voz IA selecionado.';resumePending();}\n tone(hz,duration,volume,type='sine'){if(!this.ctx||!this.enabled)return;const o=this.ctx.createOscillator(),gain=this.ctx.createGain();o.type=type;o.frequency.value=hz;gain.gain.setValueAtTime(Math.max(.0001,volume*.12),this.ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,this.ctx.currentTime+duration);o.connect(gain).connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration);}\n effect(){this.tone(440,.12,this.sfx,'triangle');setTimeout(()=>this.tone(880,.2,this.sfx,'triangle'),90);}\n eventCue(type){if(type==='gift'){this.tone(523.25,.16,this.sfx,'triangle');setTimeout(()=>this.tone(783.99,.18,this.sfx,'triangle'),95);setTimeout(()=>this.tone(1046.5,.24,this.sfx,'triangle'),195);}else if(type==='follow'){this.tone(659.25,.18,this.sfx,'sine');setTimeout(()=>this.tone(880,.22,this.sfx,'sine'),120);}else if(type==='join'){this.tone(392,.14,this.sfx,'sine');setTimeout(()=>this.tone(587.33,.18,this.sfx,'sine'),100);}else this.effect();}\n async speak(text,speaker=forms[world?.form||0],reaction=replyReaction(text)){\n if(!this.enabled)throw Error('Toque em ♫ para ativar áudio');let started=false;const onStart=()=>{if(started)return;started=true;this.speaking=true;document.body.classList.remove('voice-paused');world?.setSpeaker(speaker,true);api('adventure',{action:'react',...reaction}).then(sync).catch(()=>{});};\n try{const tts=await api('tts',{text,speaker});if(!tts.audio)throw Error('O provedor de voz IA respondeu sem áudio.');$('voice-diagnostic').textContent='VOZ IA · '+tts.model+' · '+tts.latency+' ms';await this.play(tts,onStart);}\n catch(e){$('voice-diagnostic').textContent='VOZ IA INDISPONÍVEL · '+e.message;const blocked=['missing_voice_key','gemini_400','gemini_401','gemini_403','gemini_tts_unavailable'].includes(e.code);document.body.classList.add('voice-paused');this.voiceBlocked=blocked;this.voiceRetryAt=Date.now()+(e.code==='gemini_429'?60000:15000);throw e;}\n finally{this.speaking=false;world?.setMouthOpen(0);world?.setSpeaker(speaker,false);api('adventure',{action:'locate',speaking:false}).catch(()=>{});}\n }\n play(tts,onStart=()=>{}){return new Promise((resolve,reject)=>{const binary=atob(tts.audio),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:tts.mime}));const audio=new Audio(url);this.audio=audio;audio.volume=this.voice;let source,analyser,mouthFrame;if(this.ctx){source=this.ctx.createMediaElementSource(audio);analyser=this.ctx.createAnalyser();analyser.fftSize=256;source.connect(analyser);analyser.connect(this.ctx.destination);const samples=new Uint8Array(analyser.fftSize);const meter=()=>{if(this.audio!==audio)return;analyser.getByteTimeDomainData(samples);let energy=0;for(const v of samples)energy+=((v-128)/128)**2;world?.setMouthOpen(Math.min(1,Math.sqrt(energy/samples.length)*5));mouthFrame=requestAnimationFrame(meter);};meter();}let settled=false;const done=e=>{if(settled)return;settled=true;clearTimeout(timer);audio.pause();URL.revokeObjectURL(url);this.audio=null;source?.disconnect();analyser?.disconnect();cancelAnimationFrame(mouthFrame);world?.setMouthOpen(0);e?reject(e):resolve();};const timer=setTimeout(()=>done(Error('Timeout de áudio')),30000);audio.onplaying=onStart;audio.onended=()=>done();audio.onerror=()=>done(Error('Formato de áudio não suportado'));audio.play().catch(done);});}\n\n}\nconst audio=new AudioManager(),cues=new CinematicAudio(audio),dialogue=new LiveDialogueQueue(),slides=new GiftSlideshow(document.querySelector('.omni-gifts'));\nconst classicUI=new ClassicLiveUI({forms,names,onSelect:async form=>{if(form==='base'){await action({action:'revert'});return;}$('alien-picker').hidden=false;await action({action:'select',form});}});window.classicLiveUI=classicUI;\nconst hearts=new HeartStream($('heart-layer'),{button:$('tap-tap'),modeLabel:$('tap-mode'),onTap:()=>api('event',{type:'like',user:'TAP local · DEMO',count:1}),quality:()=>world?.quality||'balanced',reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,visualEmitter:world?e=>world.energyAbsorption.receive(e):null});hearts.bindCanvas($('city'));let unlockUI=null;const goalUI=new ChatGoalUI({onSource:source=>{hearts.setSource(source);world?.energyAbsorption.setSource(source);unlockUI?.render();}});unlockUI=new AlienUnlockUI({source:()=>goalUI.source});window.benAlienUnlocks=unlockUI;window.benChatGoals=goalUI;window.benHearts=hearts;\nwindow.linelAudio=audio;window.benLiveDialogue=dialogue;\nlet state=null,revision=-1,serverOffset=0,watchID=null,lastWarning=-1,lastPowerID=null,config={},queueState={waiting:[],active:null},processing=false,processed=new Set(),announcementTimer,captionTimer,nextResponseAt=0;\n$('build-version').textContent='V'+BUILD_ID.split('.').slice(0,BUILD_ID.split('.')[1]==='0'?1:2).join('.');\nfunction notice(text){const card=document.createElement('article');card.className='toast';card.textContent=text;$('live-toasts').prepend(card);while($('live-toasts').children.length>2)$('live-toasts').lastElementChild.remove();setTimeout(()=>card.remove(),5500);}\nfunction announce(label,title){clearTimeout(announcementTimer);$('announcement-label').textContent=label;$('announcement-title').textContent=title;$('scene-announcement').hidden=false;announcementTimer=setTimeout(()=>$('scene-announcement').hidden=true,2200);}\nfunction formLabel(form){return names[forms.indexOf(form)]||form;}\nfunction sync(s){if(s.revision<revision)return;revision=s.revision;state=s;serverOffset=s.serverTime-Date.now();world?.setArenaState(s);classicUI.setForm(s.form);$('watch-form').textContent=formLabel(s.form).toUpperCase();$('watch-duration').value=s.options.durationSeconds;$('watch-recharge').value=s.options.rechargeSeconds;$('auto-wander').checked=s.options.autoWander;$('idle-life').checked=s.options.idleLife;\n if(watchID!==s.watch.id){const previous=watchID;watchID=s.watch.id;if(s.watch.phase==='selecting'){cues.play('select');$('selected-description').textContent='Selecionado: '+formLabel(s.selected)+' · confirme para transformar.';}\n  if(s.watch.phase==='transforming'){cues.play('transform');world?.startTransformationEffect(forms.indexOf(s.selected));announce('DNA SELECIONADO',formLabel(s.selected).toUpperCase());}\n  if(s.watch.phase==='recharging'){cues.play('timeout');announce('OMNITRIX DESCARREGADO','VOLTANDO A BEN');lastWarning=-1;}\n  if(s.watch.phase==='ready'&&previous!==null){cues.play('charged');notice('Omnitrix carregado! O chat já pode escolher uma forma.');}}\n for(const b of $('forms').children)b.classList.toggle('selected',b.dataset.form===s.selected);\n const active=s.motion?.status==='active';$('activity').textContent=s.watch.phase==='transforming'?'TRANSFORMAÇÃO EM ANDAMENTO':active?({walk:'Andando livre pela clareira',run:'Correndo pela clareira',dash:'XLR8 · supervelocidade',fly:'Voo livre',jump:'Salto',spin:'Rodopiando',land:'Pousando',roll:'Rolamento blindado'}[s.motion.mode]):s.stance==='sitting'?'Ben descansando · comente levantar ou andar':s.form==='base'?'Ben aguarda a próxima ideia do chat':'O chat controla '+formLabel(s.form);\n if(s.power&&s.power.id!==lastPowerID){lastPowerID=s.power.id;if(Date.now()+serverOffset-s.power.at<5000)cues.play('power-'+s.power.form);}\n renderPowers();renderWatch();unlockUI?.render();}\nfunction renderWatch(){if(!state)return;const now=Date.now()+serverOffset,w=state.watch,red=w.phase==='recharging',active=!!w.activeEndsAt,remain=Math.max(0,(red?w.endsAt:w.activeEndsAt||0)-now);$('watch-hud').dataset.phase=w.phase;const seconds=Math.ceil(remain/1000);$('watch-timer').textContent=red?'RECARGA '+seconds+'s':active?String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'):w.phase==='transforming'?'DNA…':'PRONTO';$('watch-charge').value=red?(1-remain/w.rechargeMs)*100:active?remain/w.durationMs*100:100;\n $('watch-status').textContent=red?'Vermelho · aguarde antes de transformar':w.phase==='selecting'?'DNA selecionado · '+formLabel(state.selected):w.phase==='transforming'?'Omnitrix ativado · transformação':active?(now<w.switchAt?'Forma ativa · próxima seleção em '+Math.ceil((w.switchAt-now)/1000)+'s':'Verde · tempo da forma alienígena'):'Verde · relógio carregado';\n $('confirm-transform').disabled=w.phase!=='selecting';if(active&&seconds<=5&&seconds>0&&lastWarning!==seconds){lastWarning=seconds;cues.play('low');}if(!active)lastWarning=-1;\n for(const b of $('power-choices').children)b.disabled=now<state.nextPower||w.phase==='transforming'||red&&state.form==='base';$('power-status').textContent=now<state.nextPower?'Poder recarregando · '+Math.ceil((state.nextPower-now)/1000)+'s':'Comente poder 1, poder 2 ou poder 3. Cada golpe tem sua própria animação.';}\nsetInterval(renderWatch,100);\nlet powerForm=null;\nfunction renderPowers(){if(!state||powerForm===state.form)return;powerForm=state.form;$('power-choices').replaceChildren();for(let i=0;i<3;i++){const ability=powerAbility(state.form,i),button=document.createElement('button');const badge=document.createElement('span');badge.className='power-badge';badge.textContent=FORM_ICONS[forms.indexOf(state.form)];const title=document.createElement('strong');title.textContent=(i+1)+' · '+ability.name;button.append(badge,title);const hint=document.createElement('small');hint.textContent='Chat: poder '+(i+1);button.append(hint);button.onclick=()=>action({action:'power',variant:i});$('power-choices').append(button);}}\nasync function action(data){try{const s=await api('adventure',data);sync(s);return s;}catch(e){cues.play('denied');notice(e.message);return null;}}\nfor(const [i,form] of forms.entries()){if(form==='base')continue;const b=document.createElement('button');b.textContent=names[i];b.dataset.form=form;b.onclick=()=>action({action:'select',form});$('forms').append(b);}\nconst toggle=id=>{$(id).hidden=!$(id).hidden;};\n$('open-aliens').onclick=()=>toggle('alien-picker');$('watch-select').onclick=()=>{if(state?.watch.phase==='recharging'){cues.play('denied');notice('O relógio está vermelho. Espere a recarga.');return;}$('alien-picker').hidden=false;};$('close-aliens').onclick=()=>$('alien-picker').hidden=true;\n$('confirm-transform').onclick=async()=>{if(await action({action:'confirm'}))$('alien-picker').hidden=true;};$('revert-human').onclick=()=>action({action:'revert'});\n$('open-powers').onclick=()=>toggle('power-picker');$('close-powers').onclick=()=>$('power-picker').hidden=true;\n$('open-actions').onclick=()=>toggle('quick-actions');$('close-actions').onclick=()=>$('quick-actions').hidden=true;$('toggle-test-chat').onclick=()=>{$('chat').hidden=!$('chat').hidden;$('quick-actions').hidden=true;};$('camera-home').onclick=()=>{if(world){world.audienceView.current=null;world.audienceView.pending=[];}};$('save-clock').onclick=()=>api('world-clock',{settings:{mode:$('clock-mode').value,minutes:Number($('clock-minutes').value),hour:9}}).then(s=>world?.dayCycle.sync(s)).catch(error);\n$('open-controls').onclick=()=>toggle('movement-pad');$('close-controls').onclick=()=>$('movement-pad').hidden=true;\nfor(const b of document.querySelectorAll('[data-dir]'))b.onclick=()=>action({action:'movement',mode:$('movement-mode').value,direction:b.dataset.dir.split(',').map(Number)});\nfor(const b of document.querySelectorAll('[data-gesture]'))b.onclick=()=>action({action:'gesture',kind:b.dataset.gesture});\n$('stop-movement').onclick=()=>action({action:'stop'});for(const [id,mode] of [['jump','jump'],['spin','spin'],['land','land']])$(id).onclick=()=>action({action:'movement',mode});\n$('help-toggle').onclick=()=>{toggle('command-help');$('help-toggle').setAttribute('aria-expanded',String(!$('command-help').hidden));};\n$('chat').onsubmit=async e=>{e.preventDefault();const text=$('message').value;try{await api('event',{type:'comment',user:'Você',text});$('message').value='';}catch(e){error(e);}};\nfunction ranking(rows){classicUI.ranking(rows);}\nfunction caption(text){clearTimeout(captionTimer);$('subtitles').textContent=text;}\nfunction finishCaption(){captionTimer=setTimeout(()=>$('subtitles').textContent='',10000);}\nlet voiceStage='';\nfunction queueLabel(){const s=queueState,n=s.waiting.length+Number(!!s.active);$('speech-queue').hidden=!n;$('speech-queue').textContent=!audio.enabled?'♫ ATIVE A VOZ · '+n+' na fila':(voiceStage||(s.active?.priority>=4?'★ PRIORIDADE':'🎙 FALAS'))+' · '+n+' na fila';}\nlet focusedVoiceId=null;function showQueue(s){queueState=s;queueLabel();if(s.active?.id!==focusedVoiceId){focusedVoiceId=s.active?.id;if(s.active?.viewerId)world?.audienceView.focus({id:s.active.id,source:s.active.source,viewerId:s.active.viewerId,kind:s.active.priority>=4?'gift':'comment',duration:3200});}resumePending();}\nasync function resumePending(){const item=queueState.active;if(processing||!audio.enabled||Date.now()<nextResponseAt||!item||processed.has(item.id))return;processing=true;voiceStage=item.scriptedText?'PREPARANDO FALA':'PENSANDO · '+(item.displayName||item.user);queueLabel();processed.add(item.id);if(processed.size>500)processed.delete(processed.values().next().value);try{const answer=await api('answer',{id:item.id});voiceStage='RESPONDENDO · '+(item.displayName||item.user);queueLabel();$('conversation-status').textContent=answer.mode==='local-ai'?'IA LOCAL · '+answer.model+' · '+answer.latency+' ms':answer.mode==='gemini'?'GEMINI · '+answer.model+' · '+(answer.keyLabel||'Chave selecionada'):answer.mode==='scripted'?'ROTEIRO DO BEN · voz IA':'RESPOSTA LOCAL · '+answer.warning;$('ai-mode').textContent=answer.mode==='local-ai'?'● IA LOCAL':answer.mode==='gemini'?'● GEMINI':answer.mode==='scripted'?'● BEN AO VIVO':'● RESPOSTA LOCAL';$('ai-mode').dataset.mode=answer.mode;if(answer.warning)notice(answer.warning);caption((SPEAKERS[answer.speaker]?.name||'Ben')+' ↔ '+item.user+' · '+answer.text);if(!audio.voiceBlocked&&Date.now()>=audio.voiceRetryAt)await audio.speak(answer.text,answer.speaker||state?.form||'base',answer.reaction);else{document.body.classList.add('voice-paused');$('ai-mode').textContent='● VOZ IA PAUSADA · LEGENDAS';api('adventure',{action:'react',...answer.reaction}).then(sync).catch(()=>{});}}catch(e){notice(e.message);}finally{await api('ack',{id:item.id}).catch(()=>{});processing=false;voiceStage='';queueLabel();nextResponseAt=Date.now()+((audio.voiceBlocked||Date.now()<audio.voiceRetryAt)?3000:300);finishCaption();setTimeout(resumePending,350);}}\nsetInterval(resumePending,1000);\nsetInterval(()=>api('adventure',{action:'locate',speaking:audio.speaking}).catch(()=>{}),800);\nif(world){world.onGiftShow=(event,kind,spec)=>{announce((event.source==='demo'?'DEMO · ':'PRESENTE · ')+event.gift,spec.title);cues.play(kind);};world.onPowerImpact=()=>cues.play('impact');let lastAbsorb=0;world.onEnergyAbsorb=()=>{if(performance.now()-lastAbsorb>350){cues.play('energy');lastAbsorb=performance.now();}};world.onDayPhase=phase=>{$('day-phase').textContent=({day:'☀ DIA',sunset:'◒ TARDE',night:'☾ NOITE'})[phase];};world.onAmbient=phase=>cues.play('ambient-'+phase);world.onCommunityShow=reward=>{announce(reward.kind==='unlock'?(reward.source==='demo'?'DNA LIBERADO · DEMO':'DNA LIBERADO'):(reward.source==='demo'?'MISSÃO CONCLUÍDA · DEMO':'MISSÃO CONCLUÍDA'),reward.title.toUpperCase()+(reward.combo>1?' ×'+reward.combo:''));cues.play(reward.kind==='unlock'?'charged':'goal-'+reward.effect);};}\nfunction liveStatus(s){if(['websocket confirmado','recebendo eventos'].includes(s.status))goalUI.setSource('tiktok');else if(s.status==='desconectado')goalUI.setSource('demo');const connected=['websocket confirmado','recebendo eventos'].includes(s.status);$('connection').textContent=connected?'● LIVE · '+(s.events||0)+' EVENTOS':'● '+(s.status==='desconectado'?'DEMO LOCAL':s.status||'DEMO');$('live-summary').textContent=connected?'Conectado a @'+s.username+' · '+(s.events||0)+' eventos recebidos':(s.detail||s.error||s.status||'Desconectado');$('live-diagnostic').textContent=JSON.stringify(s,null,2);}\nfunction connectStream(){const stream=new EventSource('/events');window.arenaStream=stream;stream.addEventListener('ready',e=>{const s=JSON.parse(e.data);world?.audienceView.sync(s.audience);world?.dayCycle.sync(s.worldClock);sync(s.adventure);showQueue(s.queue);ranking(s.ranking);liveStatus(s.live);classicUI.setEnergy(s.energy||0);goalUI.sync(s.chatGoals,{select:true});unlockUI.sync(s.alienUnlocks);renderAi(s.ai);});stream.addEventListener('audience',e=>world?.audienceView.sync(JSON.parse(e.data)));stream.addEventListener('audienceFocus',e=>world?.audienceView.focus(JSON.parse(e.data)));stream.addEventListener('worldClock',e=>world?.dayCycle.sync(JSON.parse(e.data)));stream.addEventListener('ai',e=>renderAi(JSON.parse(e.data)));stream.addEventListener('alienUnlocks',e=>unlockUI.sync(JSON.parse(e.data)));stream.addEventListener('alienUnlocked',e=>{const reward=JSON.parse(e.data);if(reward.source!==goalUI.source)return;notice('DNA liberado: '+reward.forms.map(a=>a.name).join(', '));world?.toonDirector.enqueue(reward);});stream.addEventListener('chatGoals',e=>goalUI.sync(JSON.parse(e.data)));stream.addEventListener('goalReward',e=>{const reward=JSON.parse(e.data);if(!goalUI.completed(reward))return;world?.toonDirector.enqueue(reward);});stream.addEventListener('adventure',e=>sync(JSON.parse(e.data)));stream.addEventListener('queue',e=>showQueue(JSON.parse(e.data)));stream.addEventListener('ranking',e=>ranking(JSON.parse(e.data)));stream.addEventListener('live',e=>liveStatus(JSON.parse(e.data)));stream.addEventListener('gameNotice',e=>notice(JSON.parse(e.data).text));stream.addEventListener('giftActions',e=>{const s=JSON.parse(e.data);$('gift-action-status').hidden=!s.length;$('gift-action-status').textContent=s.active?s.active.user+' · '+s.active.status+(s.waiting.length?' · +'+s.waiting.length+' na fila':''):'Presentes aguardando: '+s.length;});let lastLike=0;\n stream.addEventListener('event',e=>{const event=JSON.parse(e.data),p=liveEventPresentation(event);classicUI.setEnergy(event.energy||0);hearts.ingest(event);if(event.type!=='like'||Date.now()-lastLike>4500){classicUI.toast(p);if(event.type==='like')lastLike=Date.now();}if(event.type==='gift')world?.giftSpectacle.enqueue(event);else audio.eventCue(event.type);});stream.onerror=()=>$('connection').textContent='● RECONectando';}\n$('panel-toggle').onclick=()=>$('panel').showModal();$('close').onclick=()=>$('panel').close();for(const b of $('tabs').children)b.onclick=()=>{for(const id of ['live','audio','gifts','ranking','settings'])$('tab-'+id).hidden=id!==b.dataset.tab;for(const other of $('tabs').children)other.classList.toggle('active',other===b);};$('tabs').firstElementChild.click();\n$('connect').onclick=async()=>{try{localStorage.setItem('benLiveUsername',$('username').value);liveStatus(await api('connect',{username:$('username').value,provider:$('provider').value,endpoint:$('live-endpoint').value}));}catch(e){error(e);}};$('disconnect').onclick=()=>api('disconnect',{}).then(liveStatus).catch(error);$('username').value=localStorage.getItem('benLiveUsername')||'';\n$('live-shoutouts').checked=localStorage.getItem('benLiveShoutouts')!=='false';$('live-shoutouts').onchange=()=>saveConfig({hostSpeech:$('live-shoutouts').checked}).catch(error);\nasync function saveConfig(values){config=await api('config',values);applyConfig(config);}\nfunction applyConfig(c){if(config.voiceProvider!==c.voiceProvider){audio.voiceBlocked=false;audio.voiceRetryAt=0;}config=c;$('conversation-provider').value=c.conversationProvider||'gemini';$('gemini-settings').hidden=c.conversationProvider==='local';$('local-ai-setup').hidden=c.conversationProvider!=='local'&&c.voiceProvider!=='local';$('gemini-voice-settings').hidden=c.voiceProvider!=='gemini';$('eleven-voice-settings').hidden=c.voiceProvider!=='elevenlabs';audio.music=c.music;audio.voice=c.voice;audio.sfx=c.sfx;for(const n of ['music','voice','sfx'])$(n+'-volume').value=c[n];$('quality').value=c.quality;if(world)world.quality=c.quality;$('voice-provider').value=c.voiceProvider;$('tts-model').value=c.geminiTtsModel||'auto';$('gemini-voice').value=c.geminiVoice||'Puck';$('live-shoutouts').checked=c.hostSpeech;$('clock-mode').value=c.worldClock?.mode||'cycle';$('clock-minutes').value=c.worldClock?.minutes||12;$('gemini-model').value=c.conversationModel||'auto';$('eleven-voice-id').value=c.elevenVoiceId||'';$('rules').value=JSON.stringify(c.giftRules,null,2);slides.configure(c.giftRules);$('gift').replaceChildren(...c.giftRules.map(r=>{const o=document.createElement('option');o.value=o.textContent=r.name;return o;}));}\n$('unlock-settings').onsubmit=async e=>{e.preventDefault();try{unlockUI.sync(await api('alien-unlocks',{action:'configure',settings:unlockUI.settings()}),{configured:true});notice('Desbloqueios salvos. Os DNAs já conquistados foram mantidos.');}catch(e){error(e);}};$('reset-unlocks').onclick=()=>api('alien-unlocks',{action:'reset'}).then(s=>unlockUI.sync(s,{configured:true})).catch(error);\n$('goal-settings').onsubmit=async e=>{e.preventDefault();try{const settings={enabled:$('goals-enabled').checked};for(const id of ['like','comment','share','follow'])settings[id]=Number($('goal-setting-'+id).value);goalUI.sync(await api('chat-goals',{action:'configure',settings}),{select:true});notice('Metas salvas. Alterar uma meta recomeça seu progresso.');}catch(e){error(e);}};$('reset-goals').onclick=()=>api('chat-goals',{action:'reset'}).then(s=>goalUI.sync(s,{select:true})).catch(error);\n$('save-rules').onclick=async()=>{try{await saveConfig({giftRules:JSON.parse($('rules').value)});notice('Presentes salvos.');}catch(e){error(e);}};\n$('demo').onclick=()=>api('event',{type:$('demo-type').value,user:$('demo-user').value,gift:$('gift').value,count:1}).catch(error);\n$('save-watch').onclick=()=>action({action:'configure',options:{durationSeconds:Number($('watch-duration').value),rechargeSeconds:Number($('watch-recharge').value),autoWander:$('auto-wander').checked,idleLife:$('idle-life').checked}});\n$('quality').onchange=()=>saveConfig({quality:$('quality').value}).catch(error);for(const n of ['music','voice','sfx'])$(n+'-volume').oninput=e=>{audio[n]=Number(e.target.value);saveConfig({[n]:audio[n]}).catch(error);};\n$('camera-distance').value=world?.cameraZoom||1.1;$('camera-distance').oninput=e=>{if(world)world.cameraZoom=Number(e.target.value);localStorage.setItem('ben36Camera',e.target.value);};\nfunction renderKeys(s){$('key-list').replaceChildren();for(const entry of s.entries){const row=document.createElement('div'),label=document.createElement('span'),use=document.createElement('button'),remove=document.createElement('button');label.textContent=entry.label+(entry.active?' · EM USO':'');use.textContent='Usar e testar';use.disabled=entry.active;use.onclick=async()=>{try{renderKeys(await api('keys',{action:'select',id:entry.id}));await testGemini();}catch(e){error(e);}};remove.textContent='Excluir';remove.onclick=()=>api('keys',{action:'remove',id:entry.id}).then(renderKeys).catch(error);row.append(label,use,remove);$('key-list').append(row);}\n if(s.environmentAvailable){const env=document.createElement('button');env.textContent='Usar chave do ambiente';env.disabled=!s.activeId;env.onclick=()=>api('keys',{action:'select',id:null}).then(renderKeys).catch(error);$('key-list').append(env);}\n $('key-status').textContent=s.count+'/'+s.limit+' chaves · '+(s.selectedLabel?'Selecionada: '+s.selectedLabel:'Sem chave: conversa local básica.');if(s.ai)renderAi(s.ai);else api('ai-status').then(renderAi).catch(()=>{});}\n$('key-form').onsubmit=async e=>{e.preventDefault();const key=$('key-value').value;try{renderKeys(await api('keys',{action:'add',label:$('key-label').value,key,activate:true}));$('key-value').value='';$('panel-error').textContent='';await testGemini();}catch(e){error(e);}};\n$('bulk-key-form').onsubmit=async e=>{e.preventDefault();const keys=$('bulk-keys').value.split(/\\r?\\n/).map(k=>k.trim()).filter(Boolean);try{const s=await api('keys',{action:'add_many',keys});renderKeys(s);$('bulk-keys').value='';$('panel-error').textContent='';notice(s.added+' chaves adicionadas · '+s.duplicates+' repetidas ignoradas.');}catch(e){error(e);}};\nfunction renderAi(s){if(!s)return;if(s.provider==='local'){$('ai-health').dataset.state=s.state;$('ai-health').textContent=s.state==='ready'?'IA LOCAL RESPONDENDO · '+s.model:s.state==='error'?'IA LOCAL INDISPONÍVEL · '+s.message:'IA LOCAL SELECIONADA · execute e teste os serviços no aparelho.';$('ai-mode').textContent=s.state==='ready'?'● IA LOCAL':'● IA LOCAL AGUARDANDO';$('ai-mode').dataset.mode=s.state==='ready'?'local-ai':s.state;return;}const label=s.keyLabel||'nenhuma';$('ai-health').dataset.state=s.state;$('ai-health').textContent=s.state==='ready'?'GEMINI RESPONDENDO · '+label+' · '+s.model:s.state==='error'?'CHAVE SALVA · '+label+' · '+s.message:s.keyConfigured?'CHAVE SALVA · '+label+' · acesso ao Google ainda não verificado.':'SEM CHAVE SELECIONADA NO SERVIDOR';$('ai-mode').textContent=s.state==='ready'?'● GEMINI':s.state==='error'?'● IA INDISPONÍVEL':s.keyConfigured?'● CHAVE SALVA':'● RESPOSTA LOCAL';$('ai-mode').dataset.mode=s.state==='ready'?'gemini':s.state;}\nasync function testGemini(){const b=$('test-gemini');if(b.disabled)return;b.disabled=true;$('conversation-status').textContent='Testando a mesma conexão usada nas perguntas do público…';$('ai-sample').textContent='';try{const provider=$('conversation-provider').value;await saveConfig({conversationProvider:provider,...(provider==='gemini'?{conversationModel:$('gemini-model').value.trim()||'auto'}:{})});const r=await api('test-ai',{prompt:$('ai-test-prompt').value||'Qual é o seu alien favorito?'});renderAi(r.status);if(r.ok){$('conversation-status').textContent=(r.mode==='local-ai'?'IA LOCAL OK · ':('GEMINI OK · '+r.keyLabel+' · '))+r.model+' · '+r.latency+' ms'+(r.modelNotice?' · '+r.modelNotice:'');$('ai-sample').textContent=(r.mode==='local-ai'?'Resposta da IA local: ':'Resposta do Gemini: ')+r.text;$('panel-error').textContent='';audio.voiceBlocked=false;audio.voiceRetryAt=0;resumePending();}else $('conversation-status').textContent='A IA SELECIONADA NÃO RESPONDEU · '+r.warning;}catch(e){$('conversation-status').textContent='FALHA NO TESTE · '+e.message;}finally{b.disabled=false;}}\n$('test-gemini').onclick=testGemini;\n$('load-gemini-models').onclick=async()=>{const button=$('load-gemini-models');button.disabled=true;try{const r=await api('gemini-models');const auto=document.createElement('option');auto.value='auto';auto.textContent='Automático · Flash disponível';$('gemini-model-options').replaceChildren(auto,...r.models.map(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=m.name;return o;}));$('conversation-status').textContent=r.models.length+' modelos de texto listados pelo Google para a chave selecionada.';}catch(e){$('conversation-status').textContent=e.message;}finally{button.disabled=false;}};\n$('eleven-key-form').onsubmit=async e=>{e.preventDefault();const key=$('eleven-key').value;$('eleven-key').value='';try{const s=await api('voice-keys',{action:'add',label:'Minha voz',key});await api('voice-keys',{action:'select',id:s.entries.at(-1).id});$('eleven-status').textContent='Chave salva no servidor.';}catch(e){error(e);}};\n$('save-voice-provider').onclick=()=>saveConfig({voiceProvider:$('voice-provider').value,elevenVoiceId:$('eleven-voice-id').value,geminiTtsModel:$('tts-model').value.trim()||'auto',geminiVoice:$('gemini-voice').value}).then(()=>notice('Provedor salvo.')).catch(error);\n$('conversation-provider').onchange=()=>saveConfig({conversationProvider:$('conversation-provider').value}).then(()=>api('ai-status')).then(renderAi).catch(error);\n$('voice-provider').onchange=()=>{$('local-ai-setup').hidden=$('conversation-provider').value!=='local'&&$('voice-provider').value!=='local';$('gemini-voice-settings').hidden=$('voice-provider').value!=='gemini';$('eleven-voice-settings').hidden=$('voice-provider').value!=='elevenlabs';};\n$('use-local-ai').onclick=()=>saveConfig({conversationProvider:'local',voiceProvider:'local'}).then(()=>api('ai-status')).then(renderAi).catch(error);\n$('check-local-ai').onclick=async()=>{const b=$('check-local-ai');b.disabled=true;try{const r=await api('local-ai/health');$('local-ai-status').textContent='CONVERSA: '+r.text.message+'\\nVOZ: '+r.voice.message+(r.ready?'\\nPronto para testar conversa e voz.':'\\nNo Termux: bash local-ai.sh start');}catch(e){$('local-ai-status').textContent=e.message;}finally{b.disabled=false;}};\n$('sound').onclick=()=>audio.unlock().catch(error);\n$('test-tts').onclick=async()=>{if(processing)return notice('Aguarde a fala terminar.');processing=true;try{await audio.unlock();await audio.speak($('tts-test-text').value.trim()||'Agora o relógio está pronto. Quatro Braços corre rápido. Bora transformar!','base');}catch(e){error(e);}finally{processing=false;resumePending();}};\n$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{});};let wakeLock;async function awake(){if($('keep-awake').checked&&navigator.wakeLock&&document.visibilityState==='visible')wakeLock=await navigator.wakeLock.request('screen').catch(()=>null);}$('keep-awake').onchange=()=>{if($('keep-awake').checked)awake();else wakeLock?.release();};document.addEventListener('visibilitychange',()=>{awake();if(document.visibilityState==='visible')api('adventure').then(sync).catch(()=>{});});\n$('welcome').hidden=localStorage.getItem('benWelcomeBuild')===BUILD_ID;function enter(){localStorage.setItem('benWelcomeBuild',BUILD_ID);$('welcome').hidden=true;}$('enter-game').onclick=enter;$('enter-live').onclick=()=>{enter();$('panel').showModal();$('tabs').firstElementChild.click();};\ndocument.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea')||$('panel').open)return;const dir={w:[0,1],a:[-1,0],s:[0,-1],d:[1,0]}[e.key.toLowerCase()];if(dir&&!e.repeat){e.preventDefault();action({action:'movement',mode:e.shiftKey?'run':'walk',direction:dir});}else if(e.code==='Space'&&!e.repeat){e.preventDefault();action({action:'movement',mode:'jump'});}else if(['1','2','3'].includes(e.key)&&!e.repeat)action({action:'power',variant:Number(e.key)-1});});\nasync function boot(){try{applyConfig(await api('config'));const manifest=await api('models');if(world){world.modelSources=Object.fromEntries(manifest.filter(e=>e.custom||e.form!=='fourarms').map(e=>[e.form,e.url]));await world.loadFormModel('base');}for(const entry of manifest){if(!entry.author)continue;const p=document.createElement('p'),a=document.createElement('a');a.href=entry.source;a.target='_blank';a.rel='noopener noreferrer';a.textContent=entry.title+' · '+entry.author+' · '+entry.license;p.append(a);$('model-credits').append(p);}renderKeys(await api('keys'));connectStream();}catch(e){error(e);}}\nwindow.benArena={api,action,get state(){return state;},audio,cues,slides,dialogue,hearts,goalUI,unlockUI};boot();\n"
