:auto}.main-controls{display:flex;gap:7px}.main-controls button{height:43px;font-size:11px;padding:7px 10px;flex:1;border-radius:10px}#open-aliens{background:linear-gradient(135deg,#b8f66b,#85cf49);color:#153323;font-weight:900;border-color:#dcffab}#sound{flex:0 0 43px;font-size:21px;padding:4px}#sound.sound-on{color:#c7ff88;box-shadow:0 0 10px #baff8233}.activity{min-height:20px;padding:4px 7px;margin-bottom:5px;font-size:8px;background:#09251fbb;display:flex;gap:8px;align-items:center}.activity #activity{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;flex:1}#telemetry{display:none}#speech-queue{font-size:7px;white-space:nowrap;color:#d6ffa3;background:#143b2c;padding:3px 5px;border-radius:6px}#gift-action-status{max-height:22px;font-size:7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:3px 5px}#chat{margin-top:7px}#ai-mode{display:none}.voice-paused #ai-mode{display:block;bottom:98px;left:12px;font-size:7px;color:#ffe0a5;background:#3c2b17e0}.floating-panel{bottom:88px}.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.quick-grid button{min-height:47px;font-size:11px}#quick-actions{width:min(350px,calc(100% - 24px));max-height:55dvh}#subtitles{bottom:112px;left:50%;right:auto;transform:translateX(-50%);width:calc(100% - 24px);max-width:640px;font-size:13px;line-height:1.5;background:#09291ee8;border:1px solid #c6ef9755;border-radius:12px;padding:10px 13px;pointer-events:none}#subtitles:empty{display:none}#tap-tap{bottom:130px;padding:7px 9px}.tap-heart{bottom:150px}#classic-forms{margin-bottom:4px}#scene-announcement{top:46%;max-width:460px}#audience-labels{position:fixed;inset:0;z-index:5;pointer-events:none;overflow:hidden}.audience-label{position:absolute;transform:translate(-50%,-100%);display:flex;align-items:center;flex-direction:column;gap:3px;min-width:90px;max-width:150px;color:#f1ffe4;text-shadow:0 1px 3px #041a10}.audience-photo{position:relative;width:var(--photo-size,30px);height:var(--photo-size,30px);display:grid;place-items:center;border:2px solid #baff82;border-radius:50%;background:linear-gradient(135deg,#325c38,#183e3b);box-shadow:0 0 13px #bbff793a;overflow:hidden}.audience-photo img{position:absolute;width:100%;height:100%;object-fit:cover}.audience-initials{font-size:12px}.audience-label>strong{display:block;max-width:145px;font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:#0a241ddd;padding:3px 6px;border-radius:6px}.audience-label>small{font-size:5px;font-weight:900;letter-spacing:.8px;color:#ceff9c}.audience-label.supporter .audience-photo{border-color:#ffd475;box-shadow:0 0 15px #ffc35955}.audience-label.supporter>small{color:#ffd475}.audience-label.featured>strong{font-size:11px}.audience-label.featured .audience-photo{box-shadow:0 0 20px #bbff7966}\n@media(max-width:600px){.omni-energy{top:94px;left:12px;right:12px;height:64px}.omni-energy strong{font-size:9px}#watch-hud{top:165px;min-height:40px}.omni-gifts{top:213px;height:51px}#chat-goals,.omni-command-card,#command-help{top:272px}#live-ranking{top:392px}#engagement-hook{left:12px;top:391px;width:calc(100% - 184px);padding:5px 7px}#engagement-hook strong{font-size:6px}#engagement-hook span{font-size:8px}#engagement-hook b{font-size:9px}#live-toasts{top:442px}.goals-disabled #live-toasts{top:272px}#dna-next{font-size:8px}#dna-remaining{font-size:7px}#dna-icon{font-size:10px}#day-phase{font-size:6px;padding:5px 6px}.main-controls button{font-size:10px}#connection{font-size:6px;letter-spacing:0;padding:6px 7px}.logo b{font-size:21px}.logo small{font-size:5px}header{gap:6px}.audience-label>strong{font-size:8px}.audience-label.featured>strong{font-size:10px}#subtitles{font-size:12px}}\n@media(min-width:850px){.omni-energy{top:108px}#watch-hud{top:179px}.omni-gifts{top:227px}#chat-goals,#command-help{top:286px}.omni-command-card{top:102px}#live-ranking{top:235px}#engagement-hook{left:22px;top:405px}#live-toasts{top:458px}.goals-disabled #live-toasts{top:286px}.arena-bottom{left:50%;right:auto;width:570px;transform:translateX(-50%)}#tap-tap{bottom:30px;right:22px}#subtitles{bottom:110px}}\n@media(prefers-reduced-motion:reduce){.audience-photo{box-shadow:none!important}}\n\n/* Keep notifications away from faces; local tap testing lives in Actions. */\n#live-toasts,.goals-disabled #live-toasts{top:auto;bottom:183px;width:calc(100% - 24px);max-width:380px;left:12px}#live-toasts .live-toast{padding:6px 8px}#live-toasts .live-toast-icon{font-size:17px;width:24px;height:24px;flex-basis:24px}#live-toasts .live-toast-body p{display:none}#live-toasts .toast-gift .live-toast-body p{display:block;max-height:22px;overflow:hidden}#tap-tap{position:static;box-shadow:none;border-color:#baff8255;background:#173e2c;color:#d6ffad;display:flex;min-height:47px;padding:7px}#tap-tap small{color:#c5e5a4}@media(min-width:850px){#live-toasts,.goals-disabled #live-toasts{left:22px;bottom:110px;width:260px}}\n\n#live-toasts{overflow:hidden;max-height:100px;box-sizing:border-box}\n\n#local-ai-setup{border:1px solid #baff8255;border-radius:12px;background:#15372b;padding:12px;margin:12px 0}#local-ai-setup code{display:block;background:#071e17;color:#d2ff9b;padding:9px;border-radius:7px;overflow-wrap:anywhere}#local-ai-setup pre{white-space:pre-wrap}\n\n#speech-queue{font-size:8px;max-width:58%;overflow:hidden;text-overflow:ellipsis}#tts-test-text{display:block;width:100%;margin:7px 0}\n"
  },
  {
    "name": "public/chat-intent.js",
    "sha256": "a5e3a9fee7de542166fbc6ef1e1f12bfc36cdcfedb225bbacea8cae03eb3e5e5",
    "content": "// Incidental action words in a conversation must not consume the question.\nexport function isConversation(text){\n const q=String(text).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();\n return /[?？]/.test(q)||/\\b(quem|qual|quais|como|onde|quando|quanto|quantos|quantas|porque|por que|o que)\\b/.test(q)||/\\b(me (conta|conte|fala|fale|explica|explique|diz|diga)|conte (sobre|uma)|fala sobre|fale sobre|voce (acha|gosta|prefere|lembra|sabe|conhece|consegue|pode|tem)|vc (acha|gosta|sabe|pode|tem)|lembra (da|do|de)|sabe (se|sobre)|eu (acho|gosto|quero saber)|sera que)\\b/.test(q);\n}\n"
  },
  {
    "name": "public/transformations.js",
    "sha256": "569fcc2a8ee8f4edda246a59f366cffaeabf3b3fbcc55dc9ce917498b76e8052",
    "content": "import {isConversation} from './chat-intent.js';\nexport const FORM_IDS=['base','blaze','volt','rock','shade','tide','nova','beast','fourarms','cannon','wildvine'];\nexport const clean=s=>String(s).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();\nconst aliases={base:['ben 10','ben dez','humano','ben','base'],blaze:['chama','heatblast'],volt:['xlr8','xrl8','acelerado','x l r 8'],rock:['diamante','diamondhead'],shade:['fantasmatico','ghostfreak'],tide:['aquatico','ripjaws'],nova:['alien x','alienx'],beast:['besta','wildmutt'],fourarms:['quatro bracos','four arms','fourarms'],cannon:['bola de canhao','cannonbolt'],wildvine:['cipo selvagem','wildvine']};\nexport function namedTransformation(text){\n const normalized=clean(text),input=' '+normalized+' ';if(isConversation(text))return null;if(/\\b(nao|evite)\\b/.test(input))return null;\n const explicit=/\\b(transform\\w*|vir[ae]|mude?|troque?|ativ[ae]|escolh[ao]|quero ser)\\b/.test(normalized),matches=[];\n if(!explicit&&(/\\?|\\b(quem|qual|quais|como|por que|porque|onde|quando|quanto|me conte|me fala|conhece|o que)\\b/.test(String(text).toLowerCase())||/\\b(quem|qual|quais|como|por que|porque|onde|quando|quanto|me conte|me fala|conhece|o que)\\b/.test(normalized)))return null;\n for(const [form,names] of Object.entries(aliases))for(const name of names)if(input.includes(' '+name+' ')&&(explicit||normalized===name||/\\b(usa|use|solta|solte|poder|habilidade|dash|corre|correr|voa|voar)\\b/.test(normalized)))matches.push({form,length:name.length,index:input.lastIndexOf(' '+name+' ')});\n return matches.sort((a,b)=>b.index-a.index||b.length-a.length)[0]?.form||null;\n}\nexport const asksPower=text=>!isConversation(text)&&!(/\\b(nao|evite|quem|qual|quais|como|por que|porque|onde|quando|o que)\\b/.test(clean(text))||String(text).includes('?'))&&/\\b(poder|poderes|habilidade|habilidades)\\b/.test(clean(text));\nexport const POWERS={base:{name:'Scanner do relógio',color:[.5,1,.2]},blaze:{name:'Pulso de calor',color:[1,.35,.05]},volt:{name:'Arrancada veloz',color:[.1,.75,1]},rock:{name:'Cristais de sustentação',color:[.2,1,.85]},shade:{name:'Fase espectral',color:[.7,.65,1]},tide:{name:'Jato de água',color:[.1,.45,1]},nova:{name:'Campo estelar',color:[.7,.6,1]},beast:{name:'Rastreamento',color:[1,.65,.2]},fourarms:{name:'Superforça',color:[1,.2,.1]},cannon:{name:'Rolamento de impacto',color:[.85,.85,.5]},wildvine:{name:'Crescimento de cipós',color:[.3,1,.2]}};\nexport const POWER_LOADOUTS={\n base:[{id:'omnitrix-scan',name:'Varredura Omnitrix'},{id:'omnitrix-shield',name:'Escudo Omnitrix'},{id:'energy-pulse',name:'Pulso de energia'}],\n blaze:[{id:'fire-breath',name:'Sopro de fogo'},{id:'fireball',name:'Bola de fogo'},{id:'flame-burst',name:'Explosão de chamas'}],\n volt:[{id:'sonic-dash',name:'Arrancada supersônica'},{id:'speed-vortex',name:'Tornado de velocidade'},{id:'afterimage',name:'Rastro de velocidade'}],\n rock:[{id:'crystal-wall',name:'Muralha de cristais'},{id:'shard-volley',name:'Rajada de cristais'},{id:'crystal-shield',name:'Escudo de diamante'}],\n shade:[{id:'spectral-phase',name:'Fase espectral'},{id:'phantom-rush',name:'Investida fantasma'},{id:'shadow-tendrils',name:'Tentáculos sombrios'}],\n tide:[{id:'water-jet',name:'Jato de água'},{id:'tidal-wave',name:'Onda aquática'},{id:'water-shield',name:'Redemoinho protetor'}],\n nova:[{id:'cosmic-pulse',name:'Pulso cósmico'},{id:'starlight-orbit',name:'Órbita estelar'},{id:'gravity-well',name:'Campo gravitacional'}],\n beast:[{id:'scent-scan',name:'Rastreamento aguçado'},{id:'predator-pounce',name:'Salto predador'},{id:'sonic-roar',name:'Rugido sônico'}],\n fourarms:[{id:'ground-slam',name:'Impacto sísmico'},{id:'double-punch',name:'Soco duplo'},{id:'thunder-clap',name:'Palma trovejante'}],\n cannon:[{id:'cannon-roll',name:'Rolamento de impacto'},{id:'armored-charge',name:'Investida blindada'},{id:'rebound-burst',name:'Ricochete explosivo'}],\n wildvine:[{id:'vine-grab',name:'Laço de cipó'},{id:'seed-burst',name:'Rajada de sementes'},{id:'thorn-lash',name:'Chicote de espinhos'}]\n};\nexport function powerAbility(form,variant=0){const options=POWER_LOADOUTS[form]||POWER_LOADOUTS.base,index=Math.abs(Math.floor(Number(variant)||0))%options.length;return options[index];}\n\n// Questions about a movement stay in the conversation lane.\nexport function asksMovement(text){const value=clean(text);if(isConversation(text))return null;if(/\\b(nao|evite|quem|qual|quais|como|porque|onde|quando|o que)\\b/.test(value)||String(text).includes('?'))return null;if(/\\b(dash|arrancada|super velocidade)\\b/.test(value))return 'dash';if(/\\b(voa|voe|voar|voando|voo|decolar|decola)\\b/.test(value))return 'fly';if(/\\b(corre|corra|correr|corrida)\\b/.test(value))return 'run';return null;}\nexport function asksGesture(text){const value=clean(text);if(isConversation(text))return null;if(/\\b(nao|evite|quem|qual|quais|como|porque|onde|quando|o que)\\b/.test(value)||String(text).includes('?'))return null;if(/\\b(acena|acene|acenar|tchau|wave)\\b/.test(value))return 'wave';if(/\\b(comemora|comemore|comemorar|celebra|celebre|celebrar|festeja|festeje)\\b/.test(value))return 'cheer';if(/\\b(pula|pule|pular|salta|salte|saltar)\\b/.test(value))return 'jump';return null;}\n\nconst missionAliases={resgate:'rescue',rescue:'rescue',escolta:'escort',escort:'escort',entrega:'delivery',delivery:'delivery',corrida:'race',race:'race',reparo:'repair',conserto:'repair',repair:'repair',incendio:'fire',fogo:'fire',fire:'fire',defesa:'defense',defender:'defense',defense:'defense',busca:'search',investigacao:'search',procurar:'search',search:'search'};\nexport function missionRequest(text){const value=clean(text);if(isConversation(text))return null;if(String(text).includes('?')||/\\b(nao|evite|qual|quais|como|quem|porque|onde|quando)\\b/.test(value))return null;const match=value.match(/^(?:ben(?: 10)? )?(?:(?:quero|nova|uma|pedir|iniciar) )?missao(?: (.*))?$/);if(!match)return null;const words=(match[1]||'').split(' ');const kind=words.map(word=>missionAliases[word]).find(Boolean)||null;return {kind};}\n"
  },
  {
    "name": "public/arena-commands.js",
    "sha256": "d9f4dcea592991e29d86c89286158ef1f5286570f0ef5854eb55eda8342280c2",
    "content": "import {isConversation} from './chat-intent.js';\nimport {clean,namedTransformation,POWER_LOADOUTS} from './transformations.js';\nexport const ARENA_RADIUS=17;\nexport const FLYING_FORMS=['blaze','shade','nova'];\nexport const DIRECTIONS={frente:[0,1],tras:[0,-1],esquerda:[-1,0],direita:[1,0],norte:[0,1],sul:[0,-1],oeste:[-1,0],leste:[1,0]};\nexport function parseArenaCommand(text){const s=clean(text);if(isConversation(text))return null;if(!s||String(text).includes('?')||/\\b(nao|como|qual|quem|porque)\\b/.test(s))return null;\n const form=namedTransformation(text);if(form)return {kind:'transform',form};\n if(/^(ben )?(parar|pare|parado|stop)$/.test(s))return {kind:'stop'};\n if(/^(ben )?(voltar|humano|destransformar|destransforme)$/.test(s))return {kind:'revert'};\n if(/^(transformar|transforme|confirmar|ativar)$/.test(s))return {kind:'confirm'};\n if(/^(selecionar|selecione) /.test(s)){const f=namedTransformation(s.replace(/^(selecionar|selecione) /,''));if(f)return {kind:'select',form:f};}\n if(s==='treinar')return {kind:'power',variant:null};\n const power=s.match(/^(?:ben )?(?:poder|habilidade|ataque)(?: ([123]))?$/);if(power)return {kind:'power',variant:power[1]?Number(power[1])-1:null};\n for(const [id,abilities] of Object.entries(POWER_LOADOUTS))for(const [variant,a] of abilities.entries())if(clean(a.name)===s||clean(a.id)===s)return {kind:'power',variant,requiresForm:id};\n if(/^(pular|pula|pule|saltar|salta|salte)$/.test(s))return {kind:'move',mode:'jump'};\n if(/^(girar|gira|gire|rodar|rodopiar)$/.test(s))return {kind:'move',mode:'spin'};\n if(/^(acenar|acene|tchau)$/.test(s))return {kind:'gesture',gesture:'wave'};\n if(/^(?:ben )?(pose|pose de heroi|pose de super heroi)$/.test(s))return {kind:'gesture',gesture:'hero'};\n if(/^(?:ben )?(vitoria|soco pro alto|soco para o alto)$/.test(s))return {kind:'gesture',gesture:'fistpump'};\n if(/^(?:ben )?(sentar|senta|sente|descansar)$/.test(s))return {kind:'gesture',gesture:'sit'};\n if(/^(?:ben )?(levantar|levanta|levante|ficar de pe)$/.test(s))return {kind:'gesture',gesture:'stand'};\n if(/^(?:ben )?(sorrir|sorria|sorri)$/.test(s))return {kind:'gesture',gesture:'smile'};\n if(/^(?:ben )?(concordar|confirme com a cabeca)$/.test(s))return {kind:'gesture',gesture:'nod'};\n if(/^(comemorar|comemore|celebrar)$/.test(s))return {kind:'gesture',gesture:'cheer'};\n if(/^(pousar|pouse|descer|desca)$/.test(s))return {kind:'move',mode:'land'};\n const words=s.split(' '),direction=Object.keys(DIRECTIONS).find(d=>words.includes(d));let mode=/\\b(dash|super rapido|super velocidade|superrapido|acelerar)\\b/.test(s)?'dash':/\\b(voar|voa|voe|subir|suba)\\b/.test(s)?'fly':/\\b(correr|corre|corra)\\b/.test(s)?'run':/\\b(andar|anda|ande|caminhar|caminhe)\\b/.test(s)?'walk':direction?'walk':null;\n if(mode)return {kind:'move',mode,direction:direction?DIRECTIONS[direction]:null};return null;\n}\nexport function constrainArena(x,z,radius=ARENA_RADIUS){const d=Math.hypot(x,z);return d>radius?[x/d*radius,z/d*radius]:[x,z];}\n"
  },
  {
    "name": "server/core.js",
    "sha256": "e13a7cdbaceee6cb0a790fc3b0578f7c3c4772d9340928e08116991e869d881c",
    "content": "import {safeViewerAvatar} from '../public/viewer-profile.js';\nimport {isConversation} from '../public/chat-intent.js';\nimport {geminiResponseError,geminiNetworkError} from './gemini-errors.js';\nimport {parseArenaCommand} from '../public/arena-commands.js';\nimport {DEFAULT_GIFT_RULES,DEFAULT_COMMAND_RULES,giftKey,giftReaction} from '../public/audience.js';\nimport {addressedSpeaker,guardIdentity,personaSystem} from './personas.js';\nimport {classicContext,classicSystem,localClassicReply} from './classic.js';\nimport {SPEAKERS,speakerId} from '../public/characters.js';\nimport {namedTransformation,asksPower,asksMovement,asksGesture,missionRequest} from '../public/transformations.js';\nimport { randomUUID } from 'node:crypto';\nexport const FORMS=['base','blaze','volt','rock','shade','tide','nova','beast','fourarms','cannon','wildvine'];\nexport const DISTRICTS=['Praça Aurora','Jardim das Águas','Mercado Solar','Vila Cristal','Parque das Estrelas','Centro Cultural'];\nconst LIVE_RANKS=[{name:'Novato',minimum:0},{name:'Fã',minimum:25},{name:'Apoiador',minimum:100},{name:'Guardião',minimum:300},{name:'Lenda',minimum:750},{name:'Mítico',minimum:2000}];\nexport function liveRankForPoints(points){\n const score=Math.max(0,Number(points)||0);let index=0;\n for(let i=1;i<LIVE_RANKS.length;i++)if(score>=LIVE_RANKS[i].minimum)index=i;\n const current=LIVE_RANKS[index],next=LIVE_RANKS[index+1];\n return {rankName:current.name,rankLevel:index+1,nextRank:next?.name||null,nextRankAt:next?.minimum||null,rankProgress:next?Math.round(Math.min(1,(score-current.minimum)/(next.minimum-current.minimum))*100):100};\n}\nexport class EventHub {\n constructor(){this.seen=new Map();this.ranking=new Map();this.totalEnergy=0;this.giftRules=DEFAULT_GIFT_RULES.map(rule=>({...rule}));this.commandRules=DEFAULT_COMMAND_RULES.map(rule=>({...rule}));this.listeners=new Set();}\n ingest(input,source='demo'){\n  if(!['comment','gift','like','follow','share','join'].includes(input.type))throw Error('Tipo de evento inválido');\n  if(input.type==='gift'&&input.repeatEnd===false)return null;\n  const id=String(input.id||randomUUID());if(this.seen.has(id))return null;\n  if(this.seen.size>5000)this.seen.delete(this.seen.keys().next().value);this.seen.set(id,Date.now());\n  const user=String(input.user||'Visitante').slice(0,40).replace(/[<>]/g,'');const text=String(input.text||'').slice(0,500);\n  const count=Math.min(1000,Math.max(1,Number(input.count)||1));\n  const rule=input.type==='gift'?this.giftRules.find(r=>giftKey(r.name)===giftKey(input.gift||'')):null;\n  const points=input.type==='gift'?(rule?.points??5)*count:input.type==='like'?count:input.type==='follow'?5:1;\n  const entry=this.ranking.get(user)||{user,points:0,giftCredit:0,gifts:0,likes:0,follows:0,shares:0,comments:0,visits:0,events:0};\n  this.totalEnergy=Math.min(Number.MAX_SAFE_INTEGER,this.totalEnergy+points);entry.points+=points;entry.events++;entry.lastEventType=input.type;entry.lastSeen=Date.now();\n  if(input.type==='gift'){entry.gifts+=count;entry.giftCredit=Math.min(3,entry.giftCredit+1);}\n  if(input.type==='like')entry.likes+=count;\n  if(input.type==='follow')entry.follows++;\n  if(input.type==='share')entry.shares++;\n  if(input.type==='comment')entry.comments++;\n  if(input.type==='join')entry.visits++;\n  this.ranking.set(user,entry);\n  const conversational=input.type==='comment'&&isConversation(text);\n  const command=input.type==='comment'&&!conversational?this.commandRules.find(r=>r.command.toLowerCase()===text.trim().toLowerCase()):null;\n  const mission=input.type==='comment'?missionRequest(text):null;\n  const event={id,type:input.type,user,displayName:String(input.displayName||user).replace(/[<>\\x00-\\x1f]/g,'').slice(0,40),avatarUrl:safeViewerAvatar(input.avatarUrl),text,gift:String(input.gift||'').slice(0,80),count,points,powerLevel:input.type==='gift'?Math.max(1,Math.min(5,1+Math.floor(Math.log2(Math.max(1,points/10))))):1,action:command?.action||rule?.action||(input.type==='comment'?namedTransformation(text):null),movement:command?.movement||rule?.movement||(input.type==='comment'?asksMovement(text):null),gesture:command?.gesture||(input.type==='comment'?asksGesture(text):null),speaker:input.type==='comment'?addressedSpeaker(text):null,mission:!!(command?.mission||command?.missionKind||rule?.mission||rule?.missionKind||mission),missionKind:command?.missionKind||rule?.missionKind||mission?.kind||null,power:!!(command?.power||rule?.power||input.type==='comment'&&asksPower(text)),source,time:Date.now()};\n  event.direction=rule?.direction||command?.direction||null;event.powerVariant=rule?.powerVariant??command?.powerVariant??null;event.energy=this.totalEnergy;event.training=input.type==='comment'&&/^(?:\\/)?(?:treinar|treino)$/.test(text.trim().toLowerCase());\n  event.control=input.type==='comment'&&!conversational?parseArenaCommand(text):null;\n  if(conversational){event.action=null;event.movement=null;event.gesture=null;event.power=false;event.training=false;}\n  if(event.mission)event.movement=null;\n  if(event.speaker){event.action=null;event.power=false;event.mission=false;event.missionKind=null;event.movement=null;event.gesture=null;}\n  if(input.type==='gift'&&(event.action||event.power||event.movement||event.mission))event.reaction=giftReaction(event);\n  for(const f of this.listeners)f(event);return event;\n }\n leaders(){return [...this.ranking.values()].sort((a,b)=>b.points-a.points||b.events-a.events||a.user.localeCompare(b.user)).slice(0,20).map((entry,index)=>({...entry,position:index+1,...liveRankForPoints(entry.points)}));}\n}\nexport class SpeechQueue {\n constructor({onChange=()=>{},timeout=45000}={}){this.items=[];this.active=null;this.onChange=onChange;this.timeout=timeout;this.timer=null;this.completed=0;this.turn=0;this.highStreak=0;}\n enqueue(item){if(this.items.length>=((item.priority||0)>=4?50:46))return false;this.items.push({...item,id:randomUUID(),created:Date.now()});this.next();this.onChange(this.snapshot());return true;}\n switchSource(source){this.items=this.items.filter(i=>!i.source||i.source===source);this.onChange(this.snapshot());}\n promote(user,priority=5){let changed=false;for(const item of this.items)if(item.user===user&&item.kind!=='ambient'){item.priority=Math.max(priority,item.priority||0);changed=true;}if(changed)this.onChange(this.snapshot());return changed;}\n next(){if(this.active||!this.items.length)return;this.turn++;this.items.sort((a,b)=>(b.priority||0)-(a.priority||0)||a.created-b.created);const normal=this.highStreak>=2?this.items.findIndex(i=>(i.priority||0)<4):-1;this.active=this.items.splice(normal>=0?normal:0,1)[0];this.highStreak=(this.active.priority||0)>=4?this.highStreak+1:0;this.timer=setTimeout(()=>this.ack(this.active?.id),this.timeout);this.timer.unref?.();this.onChange(this.snapshot());}\n hold(id){if(this.active?.id!==id)return false;clearTimeout(this.timer);this.timer=setTimeout(()=>this.ack(id),240000);this.timer.unref?.();return true;}\n ack(id){if(!this.active||this.active.id!==id)return false;clearTimeout(this.timer);this.active=null;this.completed++;this.next();this.onChange(this.snapshot());return true;}\n snapshot(){return {active:this.active,waiting:this.items,completed:this.completed};}\n close(){clearTimeout(this.timer);}\n}\nexport function wav(pcm){const b=Buffer.alloc(44);b.write('RIFF');b.writeUInt32LE(pcm.length+36,4);b.write('WAVEfmt ',8);b.writeUInt32LE(16,16);b.writeUInt16LE(1,20);b.writeUInt16LE(1,22);b.writeUInt32LE(24000,24);b.writeUInt32LE(48000,28);b.writeUInt16LE(2,32);b.writeUInt16LE(16,34);b.write('data',36);b.writeUInt32LE(pcm.length,40);return Buffer.concat([b,pcm]);}\nlet proxyDispatcher;\nexport async function providerFetch(url,options){if(!process.env.HTTPS_PROXY&&!process.env.HTTP_PROXY)return fetch(url,options);const {fetch:proxyFetch,EnvHttpProxyAgent}=await import('undici');proxyDispatcher??=new EnvHttpProxyAgent();return proxyFetch(url,{...options,dispatcher:proxyDispatcher});}\nexport async function gemini(text,{tts=false,fetcher=providerFetch,key=process.env.GEMINI_API_KEY,speaker='base',context={},system,json=false,model:chosenModel,voiceName,history=[]}={}){\n if(!key)throw Error('GEMINI_API_KEY ausente no servidor');\n const model=tts?(chosenModel||process.env.GEMINI_TTS_MODEL||'gemini-2.5-flash-preview-tts'):(chosenModel||process.env.GEMINI_MODEL||'gemini-2.5-flash');\n const profile=SPEAKERS[speakerId(speaker)];\n // TTS reads its input literally. Keep all performance/persona directions out\n // of the spoken contents; select the timbre only through speechConfig.\n const body=tts?{contents:[{parts:[{text}]}],generationConfig:{responseModalities:['AUDIO'],speechConfig:{voiceConfig:{prebuiltVoiceConfig:{voiceName:voiceName||profile.voice}}}}}:{systemInstruction:{parts:[{text:system||(!context.arena&&personaSystem(context.speaker))||classicSystem(context)}]},contents:[...history.slice(-4).flatMap(h=>[{role:'user',parts:[{text:String(h.prompt).slice(0,500)}]},{role:'model',parts:[{text:String(h.answer).slice(0,700)}]}]),{role:'user',parts:[{text:system?text:'Referência local de continuidade (se relevante):\\n'+classicContext(text)+'\\nPergunta do espectador:\\n'+text}]}],...(json?{generationConfig:{responseMimeType:'application/json',temperature:.95}}:{})};\n const start=Date.now();let r;try{r=await fetcher('https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+':generateContent',{method:'POST',headers:{'content-type':'application/json','x-goog-api-key':key},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)});}catch{throw geminiNetworkError();}\n if(!r.ok)throw await geminiResponseError(r);const data=await r.json();const parts=data.candidates?.[0]?.content?.parts||[];\n if(tts){const audio=parts.find(p=>p.inlineData)?.inlineData;if(!audio||!audio.mimeType?.startsWith('audio/'))throw Error('Resposta sem áudio');const pcm=Buffer.from(audio.data,'base64');return {audio:(audio.mimeType.includes('L16')||audio.mimeType.includes('pcm')?wav(pcm):pcm).toString('base64'),mime:audio.mimeType.includes('L16')||audio.mimeType.includes('pcm')?'audio/wav':audio.mimeType,model,latency:Date.now()-start};}\n const answer=parts.filter(p=>!p.thought).map(p=>p.text||'').join('').trim();if(!answer)throw Object.assign(Error(data.promptFeedback?.blockReason?'O Google bloqueou esta resposta. Tente reformular a pergunta.':'O Google respondeu sem texto. Tente novamente ou use outro modelo disponível.'),{code:data.promptFeedback?.blockReason?'gemini_blocked':'gemini_empty',category:'response'});return {text:system?answer:guardIdentity(answer,context.arena?'base':context.speaker||context.form),model,latency:Date.now()-start};\n}\nexport const localReply=localClassicReply;\n"
