    "content": "import {localGoalReply} from './chat-goals.js';\nimport {gemini,localReply} from './core.js';\nimport {identityQuestion,localPersonaReply} from './personas.js';\nimport {addressBenReply} from '../public/ben-dialogue.js';\nimport {replyReaction} from '../public/ben-behavior.js';\n// Text generation and voice are independent. Never silently call local dialogue Gemini.\nexport async function answerComment(item,{key,keyLabel=null,model,provider='gemini',context={},generate=gemini}={}){\n const speaker=context.arena?(context.form||'base'):(item.speaker||context.form||'base'),persona=context.arena?'base':speaker;let warning='Cadastre e selecione uma chave Gemini para conversar com IA.',code='missing_key';const enabled=provider==='local'||!!key;\n if(enabled)try{const answer=await generate(item.prompt,{key,model,context:{...context,speaker:persona}});const text=addressBenReply(answer.text,item.displayName||item.user);return {...answer,text,speaker,mode:provider==='local'?'local-ai':'gemini',keyLabel,reaction:replyReaction(text,item.prompt)};}catch(e){warning=e.message;code=e.code||'provider_error';}\n let basic=localReply(item.prompt);if(enabled&&basic.startsWith('Essa aí eu ainda não sei! Meu comunicador está sem conexão.'))basic='Meu comunicador engasgou nessa! Repete a pergunta daqui a pouquinho?';\n const text=addressBenReply(identityQuestion(item.prompt,persona)||localGoalReply(item.prompt,context.chatGoals)||localPersonaReply(item.prompt,persona,basic),item.user);return {text,speaker,mode:'local',warning,code,keyLabel,keyConfigured:!!key,reaction:replyReaction(text,item.prompt)};\n}\n"
