    "name": "local-ai.sh",
    "sha256": "4ecec099b795b0b8ff4de2cd1551bdc47c36936fd89dfb8277260b64a6aa5962",
    "content": "#!/usr/bin/env bash\nset -euo pipefail\ntask_game_root=\"$(cd -- \"$(dirname -- \"$0\")\" && pwd)\"\ntask_local_root=\"${BEN10_LOCAL_ROOT:-$HOME/.local/share/ben10-local-ai}\"\ntask_command=\"${1:-help}\"\nshift || true\ncase \"$task_command\" in\n  install) exec bash \"$task_game_root/scripts/local-ai/install.sh\" \"$@\" ;;\n  voice)\n    if [[ $# -ne 1 || ! \"$1\" =~ ^(cadu|faber|jeff)$ ]]; then printf 'Use: bash local-ai.sh voice cadu|faber|jeff\\n' >&2; exit 1; fi\n    exec python3 \"$task_game_root/scripts/local-ai/download_models.py\" --root \"$task_local_root\" --voice \"$1\"\n    ;;\n  start|status)\n    task_node_options=()\n    if [[ -f \"$task_game_root/.env\" ]]; then task_node_options+=(\"--env-file=$task_game_root/.env\"); fi\n    exec node \"${task_node_options[@]}\" \"$task_game_root/scripts/local-ai/run.js\" \"$task_command\"\n    ;;\n  help|--help|-h)\n    printf 'Instalar uma vez: bash local-ai.sh install [--model gt3|light]\\nIniciar IA e jogo: bash local-ai.sh start\\nComparar voz brasileira: bash local-ai.sh voice cadu|faber|jeff\\nDiagnóstico: bash local-ai.sh status\\nModelos: %s\\n' \"$task_local_root\"\n    ;;\n  *) printf 'Comando inválido. Use bash local-ai.sh help\\n' >&2; exit 1 ;;\nesac\n"
