    "name": "scripts/local-ai/run.js",
    "sha256": "7255e5a9087200dbcc52c3fbd1d99400d2a18abb1b0854f32767d596d19afa12",
    "content": "import {spawn} from 'node:child_process';\nimport {createConnection} from 'node:net';\nimport {readFile,mkdir,access,open} from 'node:fs/promises';\nimport {constants,existsSync} from 'node:fs';\nimport {fileURLToPath} from 'node:url';\nimport path from 'node:path';\nimport os from 'node:os';\nimport {localHealth,loopbackRequest,localSettings} from '../../server/local-ai.js';\nimport {BUILD_ID} from '../../public/release.js';\n\nconst gameRoot=fileURLToPath(new URL('../../',import.meta.url));\nconst localRoot=path.resolve(process.env.BEN10_LOCAL_ROOT||path.join(os.homedir(),'.local/share/ben10-local-ai'));\nconst pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));\nconst children=[];let stopping=false;\nasync function cleanup(){if(stopping)return;stopping=true;for(const child of [...children].reverse())if(child.exitCode===null&&child.signalCode===null){try{process.kill(-child.pid,'SIGTERM');}catch{child.kill('SIGTERM');}}await pause(500);}\nfor(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>cleanup().then(()=>process.exit(0)));\nfunction launch(command,args,{log,cwd=gameRoot}={}){\n if(stopping)throw Error('Inicialização cancelada');\n const child=spawn(command,args,{cwd,env:process.env,detached:true,stdio:log?['ignore',log,log]:'inherit'});\n children.push(child);child.on('error',error=>{child.startError=error;});return child;\n}\nfunction portOpen(port){return new Promise(resolve=>{const socket=createConnection({host:'127.0.0.1',port});const done=value=>{socket.destroy();resolve(value);};socket.setTimeout(700,()=>done(false));socket.once('connect',()=>done(true));socket.once('error',()=>done(false));});}\nasync function waitReady(read,predicate,child,label,timeout=180000){const deadline=Date.now()+timeout;let last=0;while(Date.now()<deadline&&!stopping){if(child&&(child.exitCode!==null||child.signalCode!==null||child.startError))throw Error(label+' encerrou. Consulte os logs em '+path.join(localRoot,'logs'));try{const value=await read();if(predicate(value))return value;}catch{}if(Date.now()-last>10000){console.log('Carregando '+label+'…');last=Date.now();}await pause(500);}throw Error(label+' não ficou pronto. Confira bash local-ai.sh status e os logs.');}\nasync function main(){\n const command=process.argv[2]||'status',settings=localSettings();let manifest=null;try{manifest=JSON.parse(await readFile(path.join(localRoot,'install.json'),'utf8'));}catch{}\n if(command==='status'){console.log(JSON.stringify({installed:!!manifest,model:manifest?.textRepo||null,modelsDirectory:localRoot,...await localHealth(settings)},null,2));return;}\n if(command!=='start')throw Error('Use start ou status');\n if(!manifest)throw Error('Instale primeiro: bash local-ai.sh install');\n const llama=path.join(localRoot,'llama.cpp/build/bin/llama-server');\n await access(llama,constants.X_OK).catch(()=>{throw Error('llama-server ausente. Complete bash local-ai.sh install.');});\n for(const file of [manifest.textModel,manifest.voiceModel,manifest.voiceModel+'.json'])await access(file);\n const voiceRelative=path.relative(localRoot,path.resolve(manifest.voiceModel));\n if(voiceRelative.startsWith('..')||path.isAbsolute(voiceRelative)||!voiceRelative.endsWith('.onnx'))throw Error('O modelo de voz precisa estar na pasta local da IA.');\n if(await portOpen(settings.textPort)||await portOpen(settings.voicePort))throw Error('Uma porta da IA local já está ocupada. Se a IA já estiver pronta, execute bash start.sh. Confira bash local-ai.sh status.');\n await mkdir(path.join(localRoot,'logs'),{recursive:true});\n const llmLog=await open(path.join(localRoot,'logs/conversa.log'),'a'),voiceLog=await open(path.join(localRoot,'logs/voz.log'),'a');\n const llm=launch(llama,['--model',manifest.textModel,'--alias',settings.model,'--host','127.0.0.1','--port',String(settings.textPort),'--ctx-size','4096','--threads','4','--threads-batch','4','--batch-size','128','--ubatch-size','128','--parallel','1','--threads-http','2','--no-webui','--reasoning','off'],{log:llmLog.fd});\n const tts=launch('proot-distro',['login','--bind',localRoot+':/ben10-data','--bind',path.join(gameRoot,'scripts/local-ai')+':/opt/ben10-worker','ben10-ai','--','/opt/ben10-voice/bin/python','/opt/ben10-worker/tts_server.py','--model','/ben10-data/'+voiceRelative.split(path.sep).join('/'),'--port',String(settings.voicePort)],{log:voiceLog.fd});\n await llmLog.close();await voiceLog.close();\n await Promise.all([waitReady(async()=>JSON.parse((await loopbackRequest(settings.textPort,'/health',{timeout:2500})).data),s=>s.status==='ok',llm,'conversa'),waitReady(async()=>JSON.parse((await loopbackRequest(settings.voicePort,'/health',{timeout:2500})).data),s=>s.ready===true,tts,'voz')]);\n const gamePort=Number(process.env.PORT||3000);if(!Number.isInteger(gamePort)||gamePort<1024||gamePort>65535)throw Error('PORT do jogo inválida');\n let game=null,health;try{health=JSON.parse((await loopbackRequest(gamePort,'/api/health',{timeout:1500})).data);}catch{}\n if(health){if(health.runtime?.root!==gameRoot.replace(/\\/$/,''))throw Error('A porta do jogo pertence a outra instalação. Pare essa sessão ou escolha outra PORT.');}\n else{if(await portOpen(gamePort))throw Error('A porta do jogo está ocupada.');game=launch(process.execPath,[...(existsSync(path.join(gameRoot,'.env'))?['--env-file=.env']:[]),'server/index.js']);await waitReady(async()=>JSON.parse((await loopbackRequest(gamePort,'/api/health',{timeout:1500})).data),s=>s.ok===true,game,'jogo',30000);}\n const saved=await loopbackRequest(gamePort,'/api/config',{body:{conversationProvider:'local',voiceProvider:'local',localAi:settings}});if(saved.status!==200)throw Error('Não foi possível selecionar IA local no jogo.');\n console.log('\\nConversa e voz locais prontas, sem chave. Abra http://127.0.0.1:'+gamePort+'/?v='+BUILD_ID+' e toque em ♫.');\n console.log('Mantenha esta sessão aberta. Ctrl+C encerra somente os processos iniciados por este comando.');\n while(!stopping){for(const [child,label] of [[llm,'conversa'],[tts,'voz'],...(game?[[game,'jogo']]:[])])if(child.exitCode!==null||child.signalCode!==null||child.startError)throw Error('O serviço de '+label+' encerrou. Confira '+path.join(localRoot,'logs'));await pause(1000);}\n}\nmain().catch(async error=>{console.error(error.message);await cleanup();process.exitCode=1;});\n"
  },
  {
    "name": "scripts/local-ai/download_models.py",
    "sha256": "c142f50ca97bfd19ceff590e539392eae64df3e46b3e861fb52669be425f6ef9",
    "content": "\"\"\"Public model download, immutable revision and hash checks; no HF token needed.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nimport re\nimport shutil\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom pathlib import Path, PurePosixPath\n\nMODELS = {\n    \"gt3\": [\"unsloth/Qwen3-4B-Instruct-2507-GGUF\"],\n    \"light\": [\"Qwen/Qwen2.5-1.5B-Instruct-GGUF\"],\n}\nVOICE_REPO = \"rhasspy/piper-voices\"\nVOICE_BASE = \"pt/pt_BR/faber/medium/\"\nVOICES = {\"faber\": \"medium\", \"cadu\": \"medium\", \"jeff\": \"medium\"}\n\n\ndef voice_plan(name=\"faber\", info=None):\n    if name not in VOICES:\n        raise ValueError(\"Voz inválida: use cadu, faber ou jeff\")\n    info = metadata(VOICE_REPO) if info is None else info\n    base = f\"pt/pt_BR/{name}/{VOICES[name]}/\"\n    stem = f\"pt_BR-{name}-{VOICES[name]}\"\n    files = []\n    for filename in [stem + \".onnx\", stem + \".onnx.json\", \"MODEL_CARD\"]:\n        entry = next((f for f in info[\"siblings\"] if f[\"rfilename\"] == base + filename), None)\n        if entry is None:\n            raise ValueError(\"Catálogo de voz sem o arquivo: \" + base + filename)\n        check_record(entry)\n        files.append((filename, entry))\n    return info, files\n\n\ndef switch_voice(root, name):\n    # A voice change never downloads/rebuilds the conversation model or Debian.\n    manifest_path = root / \"install.json\"\n    if not manifest_path.is_file():\n        raise ValueError(\"Instale a IA primeiro: bash local-ai.sh install\")\n    manifest = json.loads(manifest_path.read_text())\n    info, files = voice_plan(name)\n    target = root / \"voices\" / name\n    for filename, entry in files:\n        download(VOICE_REPO, info[\"sha\"], entry, target / filename)\n    model = target / f\"pt_BR-{name}-{VOICES[name]}.onnx\"\n    config = json.loads(Path(str(model) + \".json\").read_text())\n    if config.get(\"espeak\", {}).get(\"voice\", \"\").lower() != \"pt-br\":\n        raise ValueError(\"O modelo não é português brasileiro. A voz anterior foi preservada.\")\n    # Commit the selection only after every file passed hash/language checks.\n    manifest.update(voiceModel=str(model.resolve()), voiceRepo=VOICE_REPO, voiceRevision=info[\"sha\"])\n    temp = manifest_path.with_suffix(\".json.tmp\")\n    temp.write_text(json.dumps(manifest, ensure_ascii=False, indent=2))\n    os.replace(temp, manifest_path)\n    print(\"Voz selecionada:\", model.stem, flush=True)\n    print(\"Reinicie com bash local-ai.sh start. Teste: Agora o relógio está pronto. Quatro Braços corre rápido.\", flush=True)\n    print(\"A outra voz e o modelo de conversa foram preservados. Créditos em\", target / \"MODEL_CARD\", flush=True)\n\n\nclass CatalogError(ValueError):\n    def __init__(self, repo, status, reason):\n        self.repo, self.status = repo, status\n        super().__init__(f\"Catálogo {repo}: {reason}\" + (f\" (HTTP {status})\" if status else \"\"))\n\n\ndef metadata(repo):\n    print(\"Consultando catálogo público:\", repo, flush=True)\n    try:\n        with urllib.request.urlopen(\"https://huggingface.co/api/models/\" + repo + \"?blobs=true\", timeout=45) as response:\n            raw = response.read(12 * 1024 * 1024 + 1)\n    except urllib.error.HTTPError as error:\n        raise CatalogError(repo, error.code, \"consulta sem token recusada ou endereço indisponível\") from None\n    except (urllib.error.URLError, TimeoutError):\n        raise CatalogError(repo, None, \"falha de conexão; confira a internet e tente novamente\") from None\n    if len(raw) > 12 * 1024 * 1024:\n        raise ValueError(\"Metadados muito grandes\")\n    result = json.loads(raw)\n    if result.get(\"private\") or result.get(\"gated\") not in (None, False):\n        raise CatalogError(repo, 403, \"o modo local usa apenas modelos públicos sem acesso condicionado\")\n    if not re.fullmatch(r\"[0-9a-f]{40}\", result.get(\"sha\", \"\")):\n        raise ValueError(\"Revisão do modelo inválida\")\n    return result\n\n\ndef choose_model(profile):\n    errors = []\n    for repo in MODELS[profile]:\n        try:\n            info = metadata(repo)\n            record = choose_quant(info)\n            return repo, info, record\n        except CatalogError as error:\n            if error.status not in (401, 403, 404):\n                raise\n            errors.append(str(error))\n            print(str(error) + \"; consultando a próxima opção pública configurada, se houver.\", flush=True)\n        except ValueError as error:\n            errors.append(repo + \": \" + str(error))\n    raise ValueError(\"Nenhum catálogo público compatível foi encontrado. \" + \" | \".join(errors) + \". O instalador não solicita chave; confira o diagnóstico ou use --model light.\")\n\n\ndef check_record(record):\n    digest = (record.get(\"lfs\") or {}).get(\"sha256\")\n    if digest:\n        if not re.fullmatch(r\"[0-9a-f]{64}\", digest):\n            raise ValueError(\"SHA-256 inválido: \" + record[\"rfilename\"])\n    elif not re.fullmatch(r\"[0-9a-f]{40}\", record.get(\"blobId\", \"\")):\n        raise ValueError(\"Catálogo sem hash de integridade: \" + record[\"rfilename\"])\n\n\ndef catalog_plan(profile):\n    repo, info, record = choose_model(profile)\n    check_record(record)\n    voice_info = metadata(VOICE_REPO)\n    voice_files = []\n    _, voice_files = voice_plan(\"faber\", voice_info)\n    print(\"Catálogos de conversa e voz conferidos. Não é necessária chave de API.\", flush=True)\n    return repo, info, record, voice_info, voice_files\n\n\ndef choose_quant(info):\n    files = [f for f in info.get(\"siblings\", []) if re.search(r\"(?:^|[-_])q4_k_m\\.gguf$\", f.get(\"rfilename\", \"\"), re.I) and PurePosixPath(f[\"rfilename\"]).name == f[\"rfilename\"]]\n    if len(files) != 1:\n        raise ValueError(\"O repositório não tem um único GGUF Q4_K_M. Use --model light ou confira o repositório.\")\n    return files[0]\n\n\ndef verify(path, record):\n    if not path.is_file():\n        return False\n    size = (record.get(\"lfs\") or {}).get(\"size\", record.get(\"size\"))\n    if size is not None and path.stat().st_size != size:\n        return False\n    lfs = (record.get(\"lfs\") or {}).get(\"sha256\")\n    oid = record.get(\"blobId\")\n    if not lfs and not oid:\n        raise ValueError(\"Servidor não informou o hash de integridade\")\n    digest = hashlib.sha256() if lfs else hashlib.sha1()\n    if not lfs:\n        digest.update(b\"blob \" + str(path.stat().st_size).encode() + b\"\\0\")\n    with path.open(\"rb\") as source:\n        for chunk in iter(lambda: source.read(1024 * 1024), b\"\"):\n            digest.update(chunk)\n    return digest.hexdigest() == (lfs or oid)\n\n\ndef download(repo, revision, record, destination):\n    check_record(record)\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    if verify(destination, record):\n        print(\"Já conferido:\", destination.name, flush=True)\n        return\n    filename = record[\"rfilename\"]\n    if \"..\" in PurePosixPath(filename).parts or filename.startswith(\"/\"):\n        raise ValueError(\"Nome de arquivo inválido\")\n    url = \"https://huggingface.co/\" + repo + \"/resolve/\" + revision + \"/\" + urllib.parse.quote(filename, safe=\"/\")\n    partial = destination.with_name(destination.name + \".part\")\n    if verify(partial, record):\n        os.replace(partial, destination)\n        return\n    expected = (record.get(\"lfs\") or {}).get(\"size\", record.get(\"size\"))\n    if partial.exists() and expected is not None and partial.stat().st_size >= expected:\n        partial.unlink()\n    start = partial.stat().st_size if partial.exists() else 0\n    request = urllib.request.Request(url, headers={\"Range\": f\"bytes={start}-\"} if start else {})\n    print(\"Baixando:\", destination.name, flush=True)\n    try:\n        response = urllib.request.urlopen(request, timeout=90)\n    except urllib.error.HTTPError as error:\n        raise ValueError(f\"Arquivo {repo}/{filename}: download recusado (HTTP {error.code}). O parcial foi preservado; nenhum token foi solicitado.\") from None\n    except (urllib.error.URLError, TimeoutError):\n        raise ValueError(f\"Arquivo {repo}/{filename}: falha de conexão. Repita para continuar o download parcial.\") from None\n    with response:\n        append = start > 0 and response.status == 206\n        count = start if append else 0\n        mark = count\n        with partial.open(\"ab\" if append else \"wb\") as output:\n            while True:\n                chunk = response.read(1024 * 1024)\n                if not chunk:\n                    break\n                count += len(chunk)\n                if count > 6 * 1024**3:\n                    raise ValueError(\"Modelo excede o limite de download\")\n                output.write(chunk)\n                if count - mark >= 100 * 1024**2:\n                    print(f\"  {count // 1024**2} MiB recebidos\", flush=True)\n                    mark = count\n    if not verify(partial, record):\n        partial.unlink(missing_ok=True)\n        raise ValueError(\"Hash do modelo não confere. Repita o download.\")\n    os.replace(partial, destination)\n\n\ndef install(root, profile):\n    root.mkdir(parents=True, exist_ok=True)\n    if shutil.disk_usage(root).free < 8 * 1024**3:\n        raise ValueError(\"Reserve pelo menos 8 GB livres para modelos e ambiente local\")\n    # Check both catalogs before spending time/data on the multi-GB GGUF.\n    repo, info, record, voice_info, voice_files = catalog_plan(profile)\n    model = root / \"models\" / record[\"rfilename\"]\n    download(repo, info[\"sha\"], record, model)\n    for optional in [\"README.md\", \"LICENSE\"]:\n        entry = next((f for f in info[\"siblings\"] if f[\"rfilename\"] == optional), None)\n        if entry:\n            download(repo, info[\"sha\"], entry, root / \"licenses\" / (\"text-\" + optional))\n    for name, entry in voice_files:\n        download(VOICE_REPO, voice_info[\"sha\"], entry, root / \"voices\" / name)\n    manifest = {\"profile\": profile, \"textModel\": str(model.resolve()), \"voiceModel\": str((root / \"voices/pt_BR-faber-medium.onnx\").resolve()), \"textRepo\": repo, \"textRevision\": info[\"sha\"], \"voiceRepo\": VOICE_REPO, \"voiceRevision\": voice_info[\"sha\"], \"alias\": \"ben-classico-local\", \"threads\": 4, \"context\": 2048, \"piperVersion\": \"1.8.0\", \"llamaRevision\": \"6c01da6278ab6c69ed67d9124806b50d2b299ba7\"}\n    temp = root / \"install.json.tmp\"\n    temp.write_text(json.dumps(manifest, ensure_ascii=False, indent=2))\n    os.replace(temp, root / \"install.json\")\n    print(\"Modelos conferidos. Créditos e licença da voz em\", root / \"voices/MODEL_CARD\", flush=True)\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--root\", required=True, type=Path)\n    parser.add_argument(\"--model\", choices=MODELS, default=\"gt3\")\n    parser.add_argument(\"--check\", action=\"store_true\", help=\"Conferir só os catálogos públicos, sem baixar pesos\")\n    parser.add_argument(\"--voice\", choices=VOICES, help=\"Instalar e selecionar somente uma voz, preservando a conversa\")\n    args = parser.parse_args()\n    try:\n        if args.voice:\n            switch_voice(args.root, args.voice)\n        elif args.check:\n            catalog_plan(args.model)\n        else:\n            install(args.root, args.model)\n    except Exception as error:\n        raise SystemExit(\"Download não concluído: \" + str(error))\n"
