    "content": "\"\"\"Loopback-only Piper bridge. The model is loaded once; no network or API keys.\"\"\"\nimport argparse\nimport io\nimport json\nimport threading\nimport wave\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom pathlib import Path\n\n\ndef make_server(voice, port=8082, model_name=\"pt_BR-faber-medium\", syn_config=None):\n    lock = threading.Lock()\n\n    class Handler(BaseHTTPRequestHandler):\n        def setup(self):\n            super().setup()\n            self.connection.settimeout(10)\n\n        def log_message(self, fmt, *args):\n            return\n\n        def reply(self, status, body, content_type=\"application/json\"):\n            if isinstance(body, dict):\n                body = json.dumps(body, ensure_ascii=False).encode()\n            self.send_response(status)\n            self.send_header(\"Content-Type\", content_type)\n            self.send_header(\"Content-Length\", str(len(body)))\n            self.send_header(\"Cache-Control\", \"no-store\")\n            self.send_header(\"X-Content-Type-Options\", \"nosniff\")\n            self.send_header(\"X-Ben10-Voice\", model_name)\n            self.end_headers()\n            self.wfile.write(body)\n\n        def allowed(self):\n            expected = {f\"127.0.0.1:{self.server.server_port}\", f\"localhost:{self.server.server_port}\"}\n            return self.headers.get(\"Host\") in expected and not self.headers.get(\"Origin\")\n\n        def do_GET(self):\n            if not self.allowed():\n                return self.reply(403, {\"error\": \"Acesso local apenas\"})\n            if self.path != \"/health\":\n                return self.reply(404, {\"error\": \"Rota inexistente\"})\n            self.reply(200, {\"ready\": True, \"provider\": \"piper\", \"model\": model_name})\n\n        def do_POST(self):\n            if not self.allowed():\n                return self.reply(403, {\"error\": \"Acesso local apenas\"})\n            if self.path != \"/synthesize\":\n                return self.reply(404, {\"error\": \"Rota inexistente\"})\n            try:\n                size = int(self.headers.get(\"Content-Length\", \"0\"))\n                if not 1 <= size <= 8192 or self.headers.get(\"Content-Type\", \"\").split(\";\")[0] != \"application/json\":\n                    raise ValueError()\n                payload = json.loads(self.rfile.read(size))\n                text = payload.get(\"text\")\n                if not isinstance(text, str) or not text.strip() or len(text) > 1000:\n                    raise ValueError()\n            except (ValueError, TypeError, AttributeError):\n                return self.reply(400, {\"error\": \"Fala inválida\"})\n            if not lock.acquire(blocking=False):\n                return self.reply(409, {\"error\": \"Voz ocupada\"})\n            try:\n                output = io.BytesIO()\n                with wave.open(output, \"wb\") as wav_file:\n                    # Deliberately no persona, voice directions or prefixes here.\n                    if syn_config is None:\n                        voice.synthesize_wav(text, wav_file)\n                    else:\n                        voice.synthesize_wav(text, wav_file, syn_config=syn_config)\n                audio = output.getvalue()\n                if len(audio) > 4 * 1024 * 1024:\n                    raise ValueError(\"Áudio muito grande\")\n                self.reply(200, audio, \"audio/wav\")\n            except Exception:\n                self.reply(500, {\"error\": \"Falha na síntese local. Confira o modelo de voz.\"})\n            finally:\n                lock.release()\n\n    return ThreadingHTTPServer((\"127.0.0.1\", port), Handler)\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--model\", required=True)\n    parser.add_argument(\"--port\", type=int, default=8082)\n    args = parser.parse_args()\n    if not 1024 <= args.port <= 65535:\n        parser.error(\"Porta inválida\")\n    import onnxruntime\n    from piper import PiperVoice, SynthesisConfig\n    from piper.config import PiperConfig\n\n    model = Path(args.model)\n    config = json.loads(Path(str(model) + \".json\").read_text())\n    if config.get(\"phoneme_type\", \"espeak\") != \"espeak\" or config.get(\"espeak\", {}).get(\"voice\", \"\").lower() != \"pt-br\":\n        raise ValueError(\"Use o modelo Piper pt_BR instalado pelo projeto\")\n    options = onnxruntime.SessionOptions()\n    options.intra_op_num_threads = 2\n    options.inter_op_num_threads = 1\n    voice = PiperVoice(config=PiperConfig.from_dict(config), session=onnxruntime.InferenceSession(str(model), sess_options=options, providers=[\"CPUExecutionProvider\"]))\n    server = make_server(voice, args.port, model_name=model.stem, syn_config=SynthesisConfig(length_scale=1.0))\n    print(f\"Piper pronto em 127.0.0.1:{args.port}\", flush=True)\n    try:\n        server.serve_forever()\n    finally:\n        server.server_close()\n\n\nif __name__ == \"__main__\":\n    main()\n"
